(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["az"] = {"ui":{"skip":"Məzmuna keç","back":"← AI-gile-a qayıt","lang.button":"Dil: {name}","lang.dialog":"Dil seç","lang.search":"Dil axtar","lang.none":"Heç bir dil uyğun gəlmir","lang.notYet":"{name} hələ tərcümə olunmayıb","theme.aria":"Temanı dəyiş: açıq, tünd və ya qara","theme.toLight":"Açıq temaya keç","theme.toDark":"Tünd temaya keç","theme.toBlack":"Qara temaya keç (əsl qara, OLED ekranlar üçün rahat)","words.underline":"Səhifədə bu sözlərin altından xətt çək","words.underlineHelp":"Mənasını görmək üçün nöqtəli sözün üzərinə gətir və ya ona toxun.","words.col.todo":"Hələlik seçilmiş kartlar: komanda növbəti olaraq bunlardan başlayır.","words.col.doing":"Bir AI indi bu kart üzərində işləyir.","words.col.review":"Bir AI işi bitirib; sənə çatmazdan əvvəl başqa AI yoxlayır.","words.col.verify":"Səni gözləyir: sına və işləyib-işləmədiyini de.","words.col.team":"Sənin qeydlərin və ya cavabların, komandanın götürməsini gözləyir.","words.col.done":"Bitib və qəbul edilib.","index.title":"AI-gile: süni intellekt komandan, bir lövhədə","index.description":"AI-gile süni intellektlə kodlayan komandalar üçün kanban lövhəsidir. Sən yatanda onlar işləyir; sənə qərar vermək, sınamaq və qəbul etmək üçün bir qısa yığın qalır.","hero.logoAlt":"AI-gile lövhə ikonu","hero.h1.html":"Süni intellekt komandan, bir&nbsp;lövhədə.","hero.alpha":"🐣 Qapalı pre-alfa","hero.alphaTitle":"Erkən və yarımçıq: sınadığın üçün sağ ol!","hero.lede":"Sən yatanda onlar qurur. Yuxudan durub bir qısa yığın görürsən: bir neçə sual, sınamalı bir neçə şey, bir-iki bənövşəyi almaz. Kliklə, qəbul et, çayına qayıt.","dl.windows":"Windows tətbiqi","dl.browser":"Brauzerində işlət","dl.messenger":"📱 Telefonun üçün Messenger","dl.soon":"Tezliklə","dl.notify":"🔔 Açılanda mənə xəbər ver","dl.notifySmall":"Alfa və ya beta","hero.secondary":"Çevik (agile) metoddur, amma komandanın ayaqüstü görüş qəhvəsinə ehtiyacı yoxdur. (Yenə də ayaqüstü görüş keçirirlər.)","pitch.h2":"AI-gile istədiyin qədər sözlə","pitch.lede":"Uzunluğu seç, bir sözdən 144-ə qədər. Hər uzunluq həmin ölçü üçün yazılmış ayrıca təsvirdir. Sürüşdürücünü çək və ya ox düymələrindən istifadə et.","pitch.rangeLabel":"Uzunluq (sözlə)","pitch.dice":"🎲 başqa variant","pitch.words.one":"{n} söz","pitch.words.other":"{n} söz","pitch.letters.one":"{n} hərf","pitch.letters.other":"{n} hərf","pitch.chars.one":"{n} simvol","pitch.chars.other":"{n} simvol","count.line.html.one":"İndi lövhədə {n} kart var","count.line.html.other":"İndi lövhədə {n} kart var","people.humans.html.one":"👥 {n} insan","people.humans.html.other":"👥 {n} insan","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agent","people.working.html.one":"⚡ {n} hazırda işdədir","people.working.html.other":"⚡ {n} hazırda işdədir","pre.title":"AI-gile: burada nəsə qurulur","pre.description":"Burada nəsə qurulur. Süni intellekt komandalarının istədiyini qurduğu və yol boyu sənə öyrətdiyi lövhə. Hələlik dostlarla qapalı pre-alfa.","pre.h1":"Burada nəsə qurulur. 🤫","pre.line":"Süni intellekt komandalarının istədiyini qurduğu və yol boyu sənə öyrətdiyi lövhə. Hələlik dostlarla qapalı pre-alfa.","pre.btn":"🔔 Açılanda mənə xəbər ver","pre.peek":"Şüşənin arxasında: əsl lövhə, canlı. Hər kart rəngli bir zolaqdır.","pre.peekFake":"Şüşənin arxasında: işləyən lövhə belə görünür.","pre.night":"🌙 Gecə növbətçisi işə başçılıq edir · 😴 insan dincəlir","features.aria":"Nə edir","f.pile.h":"Sənin üçün bir yığın","f.pile.html":"<b>Sənin üçün</b> bütün layihələr üzrə səni gözləyən hər şeyi saxlayır: suallar, sınanacaq şeylər, yalnız insanın edə biləcəyi işlər. Növbən nəyin sırada olduğunu və nə qədər çəkəcəyini deyir.","f.sleep.h":"Sən yatanda işləyən komandalar","f.sleep.p":"Hər layihənin lideri və süni intellekt agentlərindən ibarət komandası var. Karta rəy yaz, komanda oyanır, işi görür və yorğun insanın izləyə biləcəyi addımlarla geri verir.","f.tester.h":"Əvvəlcə süni intellekt test edən yoxlayır","f.tester.p":"Sənə heç nə çatmamış, test edən tətbiqin nüsxəsində addımları izləyir və gördüyünü ekran görüntüsü ilə göstərir. Keçənlərə göz gəzdir və bir kliklə qəbul et.","f.proof.h":"Söz yox, sübut","f.proof.p":"Hər təhvil nəyin dəyişdiyini göstərir: faylları, fərqi, ekran görüntülərini. İş bitibmi görmək üçün hər tətbiqi açmağa ehtiyac yoxdur.","f.chat.h":"Liderlərinlə söhbət et","f.chat.p":"Discord üslubunda yan sütun: hər layihəyə bir ikon, səni gözləyənlər üçün bənövşəyi almazlar. Liderə fikir yaz; o, onu kartlara və plana çevirir, ✅ Başla düyməsi ilə.","f.tidy.h":"Özünü səliqəyə salır","f.tidy.p":"Əlaqəli kartlar birləşir, qarışıq başlıqlar düzəlir, token yoxlaması isə kodu yığcam saxlayır. Keçid ediləcək şey azdır, düşünüləcək şey də.","f.private.h":"Sənindir, kompüterində","f.private.li1":"Lövhə öz maşınında işləyir və yalnız sənə cavab verir.","f.private.li2":"İnsanlar arasında şəxsi mesajlar uçdan-uca şifrələnir.","f.private.li3":"Hesab yoxdur, izləyici yoxdur, cookie yoxdur.","f.lang.h":"Öz dilində","f.lang.p":"Holland, Uels və Yapon dillərindən quldur, Yoda və Klinqon dillərinə qədər 120-dən çox dil, peşə terminləri üçün ingiliscəyə tez qayıtmaq imkanı ilə.","f.service.h":"İdeyadan əsl xidmətə","f.service.p":"AI ilə insanların indi istifadə etdiyi nəsə qurmusunuz? Onu xidmət kimi işarələyin, lövhə onu yaxşı işlətməyə kömək edəcək: işləmə yoxlamaları, açıq status səhifəsi, təhlili yazılan insidentlər, Go tələb edən dəyişikliklər, hər gün yoxlanan ehtiyat nüsxələr. Kömək hər addımı irəlilədikcə öyrədir.","msgr.h2":"AI-gile Messenger: komandan cibində","msgr.p1":"Lövhəni açmadan AI komandanla danış. Layihə liderlərinlə və dostlarınla yazış, kartın test addımlarına bax və cavab ver, hamısı telefonundan.","msgr.p2":"Qoşmaq üçün lövhəndəki QR kodu skan et. İlk dəfədir? Mehriban demo söhbət sənə hər şeyi göstərəcək.","msgr.when":"Əvvəlcə Android, sonra telefonlar və iPhone üçün veb versiya.","msgr.who":"Layihə liderin","msgr.b1":"Tünd rejim düzəlişi hazırdır. Test addımlarını istəyirsən?","msgr.b2":"Bəli, zəhmət olmasa!","msgr.b3":"1. Parametrləri aç. 2. Tünd seç. Düzgün görünür?","tl.aria":"İlk söhbətdən yol xəritəsinə qədər zaman xətti","tl.h2":"İlk söhbətdən sonrakı addıma","tl.lede":"Həqiqi tarixlər və saatlar, öz saat qurşağında. Bu gündən sonra plandır, tarix vəd edilmir.","tl.today":"Bu gün","tl.planned":"planlaşdırılıb","tl.doing":"icrada","tl.cards.one":"{n} kart","tl.cards.other":"{n} kart","join.h2":"Qoşul","join.lede":"AI-gile-ı AuDHD-li, psixi sağlamlıqla bir neçə mübarizə aparmış saqqallı bir qəribə adam və çoxlu səbirli agent qurur. Hələlik şəxsidir, dostlarla qapalı alfadadır. Açılanda sınamaq istərdin?","join.btn":"Maraq bildir","join.small":"Sənə e-poçt yazacağıq, başqa heç nə","footer.tag":"AI-gile. İzləyici yox, cookie yox, ayaqüstü görüş qəhvəsi yox.","footer.licence":"Biznes lisenziyası","footer.status":"Vəziyyət","footer.privacy":"Nə saxlayırıq","footer.thanks":"Zənglər ChilledChat sayəsində","form.sending":"Göndərilir…","form.failed":"Alınmadı: sonra yenidən yoxla.","form.offline":"AI-gile-a çatmaq olmadı: sonra yenidən yoxla.","form.keep":"Bunu yalnız sənə cavab vermək üçün istifadə edirik, sonra silirik. İzləyici yox, cookie yox.","form.keepLink":"Nə saxlayırıq","interest.title":"AI-gile: alfa açılanda mənə xəbər ver","interest.description":"AI-gile-ın qapalı alfası və ya betası açılanda xəbər tutmaq üçün e-poçtunu burax.","interest.h1":"🔔 Açılanda mənə xəbər ver","interest.lede":"AI-gile qapalı pre-alfadadır. E-poçtunu burax, sənin üçün yer olanda bir dəfə yazarıq.","interest.email":"E-poçtun","interest.which":"Hansı sınaq?","interest.alpha":"Qapalı alfa: erkən, kobud, çoxlu dəyişiklik","interest.beta":"Beta: daha sabit, sonra","interest.both":"Hansı əvvəl gəlsə","interest.submit":"Məni siyahıya yaz","interest.thanks":"Sağ ol! Siyahıdasan.","licence.title":"AI-gile: biznes lisenziyası","licence.description":"AI-gile-ı biznesində istifadə edirsən? Pulsuz biznes lisenziyası üçün müraciət et.","licence.h1":"📜 Biznes lisenziyası","licence.lede":"AI-gile-ı işdə istifadə edirsən? Kim olduğunu və nə etdiyini yaz. Bir xeyri toxunursa, lisenziya pulsuzdur.","licence.company":"Şirkət","licence.website":"Veb sayt","licence.what":"Nə ilə məşğulsan","licence.how":"Dünyaya necə kömək edir","licence.email":"E-poçt","licence.submit":"Müraciət et","licence.thanks":"Sağ ol! E-poçtla cavab verəcəyik.","status.title":"AI-gile vəziyyəti","status.h1":"AI-gile vəziyyəti","status.quiet":"Hər şey sakitdir","status.intro":"AI-gile indi işləyir? Bu səhifə hər 5 dəqiqədən bir saytı, lövhə paylaşımını, zəngləri və yükləməni yoxlayır.","status.up":"İşləyir ({ms} ms-də cavab verdi)","status.slow":"Son yoxlamaya cavab vermədi, yenidən yoxlanılır","status.down":"İşləmir: son iki yoxlamaya cavab vermədi","status.svc.web":"Sayt","status.svc.web.offers":"Bu sayt: AI-gile nədir və maraq forması","status.svc.boards":"Lövhə paylaşımı","status.svc.boards.offers":"İctimai lövhələr, dostlar arasında mesajlar və dəvətlər","status.svc.calls":"Zənglər","status.svc.calls.offers":"AI-gile-da səs, video və ekran paylaşımı","status.svc.download":"Yükləmə","status.svc.download.offers":"Windows quraşdırıcısı və dəvət linkləri","status.checking":"Yoxlanılır…","status.offline":"Vəziyyət xidmətinə indi çatmaq olmur (yenidən yoxlanılır)","status.updated":"yenilənib {ago}","status.justNow":"indicə","status.min":"{n} dəq əvvəl","status.hours":"{n} saat əvvəl","status.days":"{n} gün əvvəl","privacy.title":"AI-gile: nə saxlayırıq","privacy.h1":"Nə saxlayırıq","privacy.lede":"Qısası: yalnız bizə göndərdiyin, həm də uzun müddətə yox.","privacy.only":"Yalnız bizə göndərdiyin: formaya yazdığın, məsələn, e-poçtun. Sənin haqqında başqa heç nə.","privacy.sealed":"Serverimiz oxuya bilməsin deyə möhürlənir: göndərilməzdən əvvəl brauzerində (köhnə brauzerdə isə çatdığı an). Onu yalnız öz lövhəmiz aça bilər.","privacy.server":"Lövhəmizə çatan kimi serverdən silinir. 30 gündən sonra orada qalan hər şey onsuz da silinir.","privacy.board":"Onu lövhəmizdə yalnız sənə cavab verənə qədər saxlayırıq, sonra oradan da silirik.","privacy.none":"İzləyici yox, cookie yox, analitika yox.","privacy.local":"Dilin və açıq və ya tünd tema seçimin öz brauzerində qalır. Heç vaxt bizə göndərilmir.","privacy.ask":"Daha tez silinməsini istəyirsən? E-poçtumuza cavab yaz və bunu bildir.","live.h2":"Onun necə qurulduğunu canlı izləyin","live.caption":"Hər kart gizlidir: işin formasını görürsünüz, sözlərini yox.","live.watching.one":"canlı: {n} izləyir","live.watching.other":"canlı: {n} izləyir","live.last.now":"Son kart indicə köçürüldü","live.last.min.one":"Son kart {n} dəq əvvəl köçürüldü","live.last.min.other":"Son kart {n} dəq əvvəl köçürüldü","live.last.hour.one":"Son kart {n} saat əvvəl köçürüldü","live.last.hour.other":"Son kart {n} saat əvvəl köçürüldü","live.last.day.one":"Son kart {n} gün əvvəl köçürüldü","live.last.day.other":"Son kart {n} gün əvvəl köçürüldü","live.offline":"Canlı lövhə bir az nəfəs alır. Tezliklə yenidən baxın.","live.cols":"Backlog|Görüləcək|İcrada|Komanda yoxlayır|Sənin test etməyin üçün|Komanda üçün|Hazırdır","footer.models":"AI-gile sənin üçün AI modellərini işlədir. Onların dediyi və etdiyi özlərinə aiddir, ona görə etibar etməzdən əvvəl yoxla.","privacy.ai.h":"AI hissəsi","privacy.ai.models":"AI-gile lövhədir. İşi başqa şirkətlərin AI modelləri, məsələn Claude, Codex və Gemini, öz hesablarınla görür.","privacy.ai.check":"Onların yazdığı və etdiyi özlərindən gəlir və yanlış ola bilər. Güvənməzdən və ya yayımlamazdan əvvəl yoxla.","privacy.ai.files":"Onlar qoşduğun qovluqlarda faylları dəyişir və əmrlər icra edir. Ehtiyat nüsxə saxla.","privacy.ai.send":"Modelə verdiyin şey onu işlədən şirkətə, onların şərtləri ilə gedir. Hər şirkətin öz şərtləri və qiymətləri keçərlidir.","privacy.ai.asis":"AI-gile erkən sınaq versiyasıdır, olduğu kimi təqdim olunur."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotlar.","Həvalə."]},{"n":2,"texts":["Robot kanbanı.","Agentlər, nizamlı.","Fikirlər, qurulub."]},{"n":3,"texts":["Robotlar üçün kanban.","Fikirlər funksiyaya çevrilir.","Pulsuz agent kanbanı."]},{"n":5,"texts":["Agentlərin idarə etdiyi kanban lövhəsi.","Sən kart yazırsan. Agentlər qurur.","Pulsuz, lokal, sınaqdan keçmiş, azacıq əcaib."]},{"n":8,"texts":["Süni intellekt agentlərinin işlədiyi pulsuz kanban lövhəsi.","Fikir yaz. Agentlər onu qurur. Sən qəbul edirsən.","Bir insan və çoxlu səbirli robot üçün çeviklik."]},{"n":13,"texts":["Kompüterində olan kanban lövhəsi, kartları süni intellekt agentləri götürüb işləyir.","Fikir yaz. Agentlər komandası onu qurur. Test edən isə yoxlayır.","Pulsuz, hesabsız, izləyicisiz: bir lövhə, bir neçə robot və hər şeyi idarə edən sən."]},{"n":21,"texts":["AI-gile süni intellekt kodlama agentləri ilə işləmək üçün kanban lövhəsidir. Kartları onlar götürür, sən isə sınayıb qəbul edirsən.","Hər layihənin lideri və süni intellekt agentləri komandası olur. İstənilən karta rəy yaz, komanda dərhal işə başlayır.","Öz kompüterində işləyən pulsuz, şəxsi tapşırıq lövhəsi. İşçilər robotlardır. Hə deyən isə yalnız sənsən. Qərar həmişə səndədir."]},{"n":34,"texts":["Fikirləri lövhəyə qoyursan. Süni intellekt agentləri komandası onları işləyən funksiyalara çevirir, test edir və sınamaq üçün addımlarla geri qaytarır. Sən demədikcə heç nə bitmiş sayılmır. Hər şey şəffafdır.","AI-gile Richin indi idarə etdiyi agentlərin böyük köməyi ilə evdə düzəltdiyi kanban lövhəsidir. Pulsuzdur, kompüterində işləyir və dostlarla paylaşılır, satılmır. Bu, sadə, açıq və dostcasına bir layihədir, heç bir qəliz şərti yoxdur.","Backlogdan Bitdiyə qədər sütunları olan adi kanban lövhəsini təsəvvür et, yalnız kartları süni intellekt agentləri götürür. Gedişatı bildirir, ilişəndə soruşur və həmişə sənin razılığını gözləyir. Hər şey gözünün qabağındadır."]},{"n":55,"texts":["AI-gile komandası süni intellekt agentlərindən ibarət olan kanban lövhəsidir. Hər layihənin işi planlayan lideri və onu quran köməkçiləri var. Funksiya hazır olanda süni intellekt test edən onu sınayır və ekran görüntüsü çəkir, sonra o, sənin yığınına düşür. Qəbul et və ya rəy yaz, onlar yenidən işləsinlər. Heç nə gizlində baş vermir.","Hər şey bir nəfərin eyni vaxtda çoxlu süni intellekt kodlama sessiyasını izləmək üsulu kimi başladı və real lövhəyə çevrildi. Maşınında işləyir, hesab tələb etmir, izləyicisi yoxdur. Dostlar və maraqlananlar üçün pulsuzdur. Həm də yarımçıqdır, ona görə kobud yerlər və arabir sürprizlər gözlə. Bir sözlə, sakit və səmimi bir layihədir.","Budur dürüst variant. Fikirləri yenə də sən tapmalısan, nəticələri də yenə sən yoxlamalısan. AI-gile isə arada olan hər şeyi edir: kartları sıraya salır, rəy yazanda lazımi agenti oyadır, nəyin dəyişdiyini dəqiq göstərir və hamısını sənin üçün bir qısa yığında saxlayır. Qısası, hər şey sakit və aydın gedir."]},{"n":89,"texts":["AI-gile öz kompüterində işlətdiyin pulsuz kanban lövhəsidir. İnsanların əvəzinə hər layihənin süni intellekt agentləri komandası var: fikirlərini kartlara və plana çevirən lider və kartları prioritet sırası ilə götürən köməkçilər. Nəsə qurulanda süni intellekt test edən sınaq addımlarını izləyir və gördüyünü sənə göstərir. Sonra o, Sənin üçün adlı bir yığında gözləyir. Qəbul edirsən, ya da rəy yazırsan və komanda yenidən cəhd edir. Sənsiz heç nə heç vaxt Bitdi sütununa çatmır. Hamısı sənin kompüterində qalır.","Gözləmədiyin bəzi imkanlar var. Gecə növbəsi sən yatanda Görüləcək sütununu doldurur və səndən cavab tələb etməyən kartları seçir. Token sayğacı agentlərin bu gün və bu həftə nə qədər işlətdiyini göstərir, Tokensiz rejim isə onlara xərcləməyi dayandırmağı deyir. Dostlarına mesaj yaza bilərsən, şəxsi mesajlar uçdan-uca şifrələnir. Lövhə holland, flamand, quldur və klinqon daxil təxminən 120 dildə danışır. Bunların heç biri bir qəpik də tutmur, və heç kim də bunu sənə satmağa çalışmır. Yəni hər şey sakit və sadə qalır.","AI-gile kiçik, şəxsi layihədir, şirkət deyil. Rich bir neçə süni intellekt kodlama layihəsinə baxmaq istəyirdi, amma hər tətbiqi açıb yoxlamadan. Ona görə o və agentlər bunun üçün lövhə qurdular, sonra da lövhənin qalan hissəsini qurmaq üçün ondan istifadə etdilər. İndi qapalı pre-alfadadır, yəni bir ovuc dost üçün, əsasən, işləyir. Qiymət səhifəsi yoxdur, xəbər bülleteni yoxdur, böyümə planı yoxdur. Faydalı görünürsə, bir az daha açılanda sınamaq üçün xahiş edə bilərsən. Tələsmə, hər şey sakit gedir."]},{"n":144,"texts":["AI-gile bir insan və çoxlu süni intellekt agenti üçün kanban lövhəsidir. Öz kompüterində işləyir və tamamilə pulsuzdur. Layihələr əlavə edirsən, hər layihəyə lider və kiçik komanda düşür. Liderlə bir az Discord kimi söhbət edib fikri təsvir edirsən; lider onu kartlara və plana çevirir, sonra sənin Başla düyməsini basmağını gözləyir. Komanda kartları prioritet sırası ilə dil modelləri üçün hazırlanmış sadə əmr sətrindən istifadə edərək işləyir. Hər şey sənə qayıtmamışdan əvvəl süni intellekt test edən tətbiqin nüsxəsində addımları izləyir və ekran görüntüsü əlavə edir. Bitmiş iş dəyişən fayllar və fərqlə birlikdə sənin yığınına düşür. Qəbul edirsən, ya da rəy qoyursan, komanda oyanıb yenidən cəhd edir. Kartı Bitdi sütununa yalnız sən keçirə bilərsən. Hər şey əvvəldən axıra gözünün qabağındadır.","AI-gile ilə bir gün, təxminən. Axşam bir neçə rəy qoyursan: bu düymə yanlış yerdədir, bu siyahı sıralanmalıdır, tünd rejim ola bilərmi. Yatırsan. Agentlər rəyləri oxuyur, dəyişiklikləri edir, test edir və sənə qaytarır. Görüləcək sütunu boşalarsa, gecə növbəsi onu backlogdan səndən cavab tələb etməyən kartlarla doldurur. Səhər bir qısa yığın olur: bir neçə sual və sınamalı bir neçə şey, hər birinin yuxulu adamın izləyə biləcəyi addımları və işlədiyini göstərən ekran görüntüsü var. Kliklə keçirsən, yaxşıları qəbul edirsən, qalanını geri göndərirsən. Token sayğacı hamısının nə işlətdiyini göstərir, arıq həftələr üçün Tokensiz rejim var. Sonra səhər yeməyi yeyirsən, bunda agentlər hələ kömək edə bilmir. Bütün bunlar sənin öz tempində gedir: heç kim səni tələsdirmir, heç nə səni sıxmır. İstəsən, gün ərzində də baxa bilərsən, çünki hər şey həmişə yerindədir.","Əvvəlcə AI-gile nə deyil. O, startap deyil, satılmır və heç kim məlumatlarını toplamır. Kompüterində işləyən pulsuz lövhədir, hesabsız, izləyicisiz və cookie-siz. Nə isə: bütün süni intellekt kodlama layihələrini bir yerdə görmək üçün səliqəli bir məkan, kartları agentlər komandası edir, qərarları isə sən verirsən. Əlaqəli kartları birləşdirir, qarışıq başlıqları düzəldir və kodun nə qədər yığcam qaldığına nəzər salır. Holland və flamanddan quldur və klinqon dilinə qədər təxminən 120 dildə danışır. Dostlar bir-birinə şəxsi və şifrələnmiş mesaj yaza bilər. Onu Rich və çoxlu səbirli agent qurub, əsasən özündən istifadə edərək. Qapalı pre-alfadadır, ona görə yerlərdə kobuddur. Əgər əyləncəli görünürsə, nəzakətlə xahiş et, bəlkə erkən girdin. Dostların üçün qapı açıqdır. Maraqlanırsansa, bir az səbir et, tezliklə növbə sənə çatacaq, bir də yoxla."]}],"quips":{"1":"Bir söz. Cəsarətli. Bəlkə də çox cəsarətli.","3":"Üç söz. Artıq çox məhsul səhifəsindən dürüstdür.","8":"Səkkiz söz. Yenə də ayaqüstü görüşdən qısadır.","21":"Yeri gəlmişkən, uzunluqlar story point-dir. Əlbəttə ki, elədir.","55":"Əlli beş söz. Sən bunu oxuyanda iki kart bitdi.","144":"Bu uzun olanıdır. 233 yoxdur. Agentlər yatmağa gedib."}},"timeline":{"first-idea.name":"İlk fikir","first-idea.line":"Hələ heç bir kod olmadan ən ilk söhbət.","first-board.name":"İlk lövhə","first-board.line":"Öz qurulmasını izləyən lövhə: kartlar, sütunlar, sürüklə-burax, layihələr.","team-roles.name":"Komanda və rollar","team-roles.line":"Agent profilləri, komanda şablonları, məkanlar və kim nə edir.","install.name":"Quraşdırma və buraxılışlar","install.line":"Dostun quraşdıra biləcəyi zip, özünüyeniləmə, kanallar və geri qaytarma.","usage-saver.name":"İstifadə qənaəti","usage-saver.line":"İşə salmaların nəyə başa gəldiyini ölç, kodu yığcam saxla, limitini qoru.","friends.name":"Dostlar və paylaşım","friends.line":"Şəxsi mesajlar, şifrələnmiş relay, dəvətlər, rollar və paylaşılan layihələr.","languages.name":"Dillər","languages.line":"Hər ekran mətni dil faylında, əvvəlcə holland və flamand.","ai-tester.name":"Süni intellekt test edən","ai-tester.line":"Test edən hər təhvili əvvəlcə yoxlayır və gördüyünü göstərir.","website.name":"Veb sayt","website.line":"aigile.lol, təqdimat səhifəsi və bu zaman xətti.","streaming.name":"Söhbət və yayım","streaming.line":"Discord, Twitch, OBS, yayımçı rejimi, GIF-lər və emojilər.","no-ai.name":"Süni intellektsiz buraxılış","no-ai.line":"Süni intellektsiz kodlayanlar üçün lövhə və açıq lövhələr.","night-watch.name":"Gecə növbəsi","night-watch.line":"Növbətçi və Scrum Master sən yatanda komandaları işdə saxlayır.","p-more.name":"Qalan hər şey","p-more.line":"Növbəsini gözləyən kiçik fikirlər.","p-android.name":"Telefon və Android","p-android.line":"Lövhənə telefondan çat, sonra doğma Android tətbiqi.","p-release.name":"Alfa və sonrası","p-release.line":"Qapalı alfa, canlı sayt, sonra beta.","p-languages.name":"Daha çox dil","p-languages.line":"130 dil və öyrənənlər üçün immersiya rejimi.","p-engines.name":"Daha çox süni intellekt mühərriki","p-engines.line":"Hər agent üçün Claude, Codex, Gemini, Copilot və ya Cursor seçin.","p-pro.name":"Peşəkar təcrübə","p-pro.line":"Risk etiketləri, birləşdirmə keçidləri, insident kartları və qoruyucu çərçivələr.","p-self.name":"Sənə qulluq","p-self.line":"Yorğunluq rejimi, özünə qayğı xatırlatmaları və 4:20.","p-servers.name":"Serverlər və miqyas","p-servers.line":"Qlobal server ayarları, rollar və böyümə planlaşdırması.","p-livestream.name":"Yayım əlavələri","p-livestream.line":"Twitch söhbəti, fərdi emojilər və açıq canlı baxış."},"words":{"button":"📖 Peşə terminləri","h":"📖 Sözlərin izahı","intro":"Sadə dildə pulsuz təlim: ilk fikirdən insanların arxalandığı xidmətə qədər qarşılaşdığın hər söz; yolda Agile, qurmaq, onu təhlükəsiz və işlək saxlamaq və AI ilə işləmək.","search":"Söz axtar…","none":"Belə söz yoxdur.","close":"Bağla","count":{"one":"{count} söz","other":"{count} söz"},"groups":[{"id":"idea","name":"💡 Fikir və kəşf"},{"id":"plan","name":"🗺️ İşin planlaşdırılması"},{"id":"agile","name":"🔁 Çevik (Agile) iş qaydaları"},{"id":"build","name":"🛠️ Qurmaq"},{"id":"test","name":"🧪 Test və keyfiyyət"},{"id":"change","name":"🔀 Təhlükəsiz dəyişmək"},{"id":"run","name":"🛎️ Xidməti işlətmək"},{"id":"sec","name":"🔒 Təhlükəsizlik və məxfilik"},{"id":"ai","name":"🤖 AI ilə işləmək"},{"id":"money","name":"💰 Pul və lisenziyalar"}],"list":[{"id":"discovery","g":"idea","word":"Kəşf mərhələsi (Discovery)","text":"Bir şey qurulmazdan əvvəl hansı problemi kim üçün həll etməyə dəyər olduğunu öyrənən ilkin mərhələ.","also":["discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problemin ifadəsi","text":"Kimin problemi olduğunu, onun nə olduğunu və nə üçün vacib olduğunu deyən bir-iki cümlə; beləliklə hamı eyni hədəfə baxır.","also":["problem ifadəsi","problem statement"]},{"id":"user","g":"idea","word":"İstifadəçi","text":"Düzəltdiyin şeydən istifadə edən adam. İş onun ehtiyacları üçün görülür.","also":["istifadəçilər"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Maraqlı tərəf","text":"İşin necə nəticələnməsi ilə maraqlanan və ya ondan təsirlənən hər kəs, məsələn, ödəyənlər, istifadə edənlər və ya dəstək verənlər.","also":["maraqlı tərəflər","stakeholder"]},{"id":"persona","g":"idea","word":"Persona","text":"İstifadəçilərin bir növünü təmsil edən uydurma, lakin real görünən adam; belə ki, komanda «Sam bunu asan tapardımı?» deyə soruşa bilir.","also":["personalar"]},{"id":"userresearch","g":"idea","word":"İstifadəçi araşdırması","text":"Təxmin etmək əvəzinə real insanlarla danışıb onları müşahidə edərək nəyə ehtiyacları olduğunu öyrənmək.","also":["istifadəçi müsahibələri","user research"]},{"id":"journey","g":"idea","word":"İstifadəçi yolu","text":"Bir adamın nəyisə etmək üçün atdığı addımlar: ilk eşitməsindən sona çatana qədər, məhsulundan kənarda da. Onu çəkəndə harada ilişdiyi görünür.","also":["istifadəçi yolları","müştəri yolu","user journey"]},{"id":"painpoint","g":"idea","word":"Ağrılı nöqtə","text":"İnsanları bu gün cana gətirən və ya ləngidən şey. Yaxşı məhsullar ağrılı nöqtələri aradan qaldırır.","also":["ağrılı nöqtələr","pain point"]},{"id":"assumption","g":"idea","word":"Fərziyyə","text":"İnandığın, amma hələ yoxlamadığın şey. Fərziyyələri yazanda nəyi əvvəl yoxlamaq lazım olduğu görünür.","also":["fərziyyələr","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotez","text":"Yoxlamağı planlaşdırdığın ən yaxşı təxmin və nə baş verəcəyini gözlədiyin, məsələn, «ilk ay pulsuz olsa, insanlar qeydiyyatdan keçəcək».","also":["hipotezlər","hypothesis"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"Fikrin işlədiyini bilmək üçün, ona çox bel bağlamazdan əvvəl edilən kiçik planlı sınaq.","also":["eksperimentlər","experiment"],"noTip":1},{"id":"poc","g":"idea","word":"Konsepsiyanın sübutu (PoC)","text":"Fikrin ümumiyyətlə işləyib-işləmədiyini görmək üçün sürətli, kobud cəhd. Cavabı alandan sonra adətən atılır.","also":["PoC","proof of concept","konsepsiyanın sübutu"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Məhsulun ilk modeli, çox vaxt kliklənən şəkillər; düzgün qurmazdan əvvəl fikri insanlarda sınamaq üçün.","also":["prototiplər","prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe (ekran sxemi)","text":"Ekranın sadə eskizi: rəng və real məzmun olmadan şeylərin harada duracağını göstərir.","also":["wireframe-lər","ekran sxemi"]},{"id":"mockup","g":"idea","word":"Mockup (maket)","text":"Ekranın necə görünəcəyinin real rəng və mətnlə ətraflı şəkli, amma hələ heç nə işləmir.","also":["mockup-lar","mock-up","maket"]},{"id":"bizcase","g":"idea","word":"Biznes əsaslandırması","text":"Layihəni etmək üçün səbəblər: nəyə başa gəlir, nə gətirir və ya nəyə qənaət edir, riskləri nələrdir.","also":["biznes əsaslandırmaları","business case"]},{"id":"feasibility","g":"idea","word":"Reallaşma imkanı (feasibility)","text":"Bir şeyin əlindəki vaxt, pul və bacarıqla həqiqətən qurulub saxlanıla bilməsi.","also":["feasibility","mümkünlük"]},{"id":"outcome","g":"idea","word":"Outcome (istənilən nəticə)","text":"İnsanlar üçün istədiyin dəyişiklik, məsələn, daha az qaçırılmış görüş. Nə qədər şey qurduğundan daha vacibdir.","also":["outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output (hazırlanan iş)","text":"Komandanın hazırladığı şey, məsələn, yeni ekran və ya hesabat. Onu hazırlamaq özlüyündə kiməsə kömək etdiyi demək deyil.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Uğur göstəricisi","text":"İşin məqsədinə çatıb-çatmadığını göstərən rəqəm, məsələn, sifarişini sona çatdıranların artması.","also":["uğur göstəriciləri","success metric"]},{"id":"kpi","g":"idea","word":"Əsas performans göstəricisi (KPI)","text":"İşlərin yaxşı getdiyini görmək üçün izlədiyin vacib rəqəm, məsələn, həftəlik qeydiyyatların sayı.","also":["KPI","KPI-lər","key performance indicator"]},{"id":"okr","g":"idea","word":"Məqsədlər və əsas nəticələr (OKR)","text":"Məqsəd qoyma üsulu: məqsəd nəyi istədiyini deyir, bir neçə əsas nəticə isə ora çatdığını göstərən rəqəmlərdir.","also":["OKR","OKR-lər"]},{"id":"product","g":"plan","word":"Məhsul","text":"İstifadəçiləri üçün qurulan və saxlanılan şey, məsələn, tətbiq, sayt və ya alət.","also":["məhsullar","product"],"noTip":1},{"id":"vision","g":"plan","word":"Məhsul vizyonu","text":"Məhsulun kimə kömək etdiyini və uzunmüddətli hara getdiyini deyən qısa bəyanat.","also":["vizyon","vision statement"]},{"id":"po","g":"plan","word":"Məhsul sahibi (PO)","text":"Nəyin və hansı sıra ilə qurulacağına qərar verən adam, beləliklə komanda həmişə ən vacib işlə məşğul olur. AI-gile-də bu sənsən.","also":["PO","məhsul sahibləri","product owner"]},{"id":"pm","g":"plan","word":"Məhsul meneceri (PM)","text":"Məhsulun istiqamətinə baxan adam: hansı problemləri, kimin üçün və nə üçün həll edir. PM həm də layihə meneceri demək ola bilər, ona görə hansı olduğunu yoxla.","also":["məhsul menecerləri","product manager"]},{"id":"projmgr","g":"plan","word":"Layihə meneceri","text":"Layihəni vaxtında və büdcə daxilində saxlayan, kimin nəyi nə vaxta qədər etdiyini izləyən adam.","also":["layihə menecerləri","project manager"]},{"id":"roadmap","g":"plan","word":"Yol xəritəsi (roadmap)","text":"Növbəti aylarda nələrin gələcəyinin sıra ilə kobud planı. Dəqiq tarixləri yox, istiqaməti göstərir və öyrəndikcə dəyişir.","also":["yol xəritələri","roadmap"]},{"id":"milestone","g":"plan","word":"Milestone (nəzarət nöqtəsi)","text":"Layihədə qeyd etməyə dəyər bir nöqtə, məsələn, «ilk versiya canlıdır» və ya «100 istifadəçi».","also":["milestone","milestones","nəzarət nöqtələri"]},{"id":"mvp","g":"plan","word":"Minimum işlək məhsul (MVP)","text":"Real insanlar üçün hələ də faydalı olan ən kiçik məhsul versiyası; onlardan erkən öyrənə biləsən deyə.","also":["MVP","MVP-lər","minimum viable product"]},{"id":"requirement","g":"plan","word":"Tələb","text":"Hazır məhsulun etməli və ya olmalı olduğu şey.","also":["tələblər","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Əhatə dairəsi (scope)","text":"İşə nələrin daxil olduğu və, eyni dərəcədə vacib, nələrin daxil olmadığı.","also":["əhatə dairəsinə daxil","əhatə dairəsindən kənar","scope"]},{"id":"scopecreep","g":"plan","word":"Əhatənin şişməsi (scope creep)","text":"İşə əlavə vaxt və ya xərc barədə heç kim razılaşmadan getdikcə daha çox şey əlavə olunması; nəticədə iş heç vaxt bitmir.","also":["scope creep","feature creep","funksiya şişməsi"]},{"id":"feature","g":"plan","word":"Funksiya (feature)","text":"Məhsulun insanlar üçün edə biləcəyi bir şey, məsələn, «parolu sıfırla».","also":["funksiyalar","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epik (epic)","text":"Birdəfəyə görülməyəcək qədər böyük iş parçası; ona görə daha kiçik kartlara bölünür.","also":["epiklər","epic"]},{"id":"story","g":"plan","word":"İstifadəçi hekayəsi (user story)","text":"İstifadəçinin gözü ilə yazılmış kiçik iş: «Alıcı olaraq səbətimi saxlamaq istəyirəm ki, sonra bitirə bilim.» Nəyin qurulacağı barədə söhbətə start verir.","also":["istifadəçi hekayələri","user story"]},{"id":"ac","g":"plan","word":"Qəbul meyarları (AC)","text":"Bir kartın hazır sayılması üçün keçməli olduğu, iş başlamazdan əvvəl razılaşdırılan yoxlamalar, məsələn, «çıxıb yenidən girəndən sonra səbət hələ də yerindədir».","also":["AC","qəbul meyarı","acceptance criteria"]},{"id":"task","g":"plan","word":"Tapşırıq","text":"Görülməli tək bir iş, çox vaxt daha böyük hekayənin kiçik bir addımı.","also":["tapşırıqlar","task"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket (ticket)","text":"Kartın başqa adı: başdan sona izlənən bir iş parçası və ya bir sorğu.","also":["tiketlər","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioritet","text":"Bir şeyin hər şeylə müqayisədə nə qədər vacib və ya təcili olması; ən vacib iş birinci getsin deyə.","also":["prioritetlər","priority"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritetləşdirmə","text":"İşi vacibliyə görə sıralamaq. Geniş yayılmış üsul MoSCoW-dur: mütləq lazım (Must), olmalıdır (Should), ola bilər (Could), bu dəfə yox (Won't).","also":["prioritetləşdirmək","MoSCoW","prioritetlərin müəyyənləşdirilməsi"]},{"id":"estimate","g":"plan","word":"Qiymətləndirmə (estimate)","text":"İş parçasının nə qədər böyük və ya uzun olduğuna dair ən yaxşı təxmin. Bu təxmindir, söz deyil.","also":["qiymətləndirmələr","estimate","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Hekayə xalları (story points)","text":"İşin ölçüsünü saatla yox, kartları bir-biri ilə müqayisə edərək («bundan təxminən iki dəfə böyük») təxmin etmək üsulu. Komandaları müqayisə etmək üçün deyil.","also":["story point","story points","hekayə xalı"]},{"id":"tshirt","g":"plan","word":"Futbolka ölçüləri (T-shirt sizing)","text":"İşin ölçüsünü S, M, L və ya XL kimi təxmin etmək. Sürətlidir və erkən planlaşdırma üçün kifayətdir.","also":["t-shirt sizes","t-shirt sizing","futbolka ölçüsü"]},{"id":"poker","g":"plan","word":"Planlaşdırma pokeri","text":"Qiymətləndirmə oyunu: hamı eyni anda ölçü kartını göstərir, sonra ən yüksək və ən aşağı verən səbəbini izah edir.","also":["Scrum poker","planning poker"]},{"id":"dependency","g":"plan","word":"Asılılıq","text":"Bir iş parçasının başqası bitməyincə başlaya və ya bitə bilməməsi.","also":["asılılıqlar","dependency"]},{"id":"blocker","g":"plan","word":"Əngəl (blocker)","text":"İşin hazırda irəliləməsinə mane olan hər şey, məsələn, çatışmayan cavab və ya sınmış alət.","also":["əngəllər","blocker"]},{"id":"deadline","g":"plan","word":"Son tarix (deadline)","text":"Bir şeyin bitməli olduğu tarix.","also":["son tarixlər","deadline","bitmə vaxtı"],"noTip":1},{"id":"deliverable","g":"plan","word":"Təhvil veriləcək nəticə","text":"İşin ortaya qoyub təhvil verdiyi konkret şey, məsələn, işləyən səhifə və ya hesabat.","also":["deliverable","təhvil məhsulu"]},{"id":"forecast","g":"plan","word":"Proqnoz","text":"İndiyədək bildiklərinə görə nəyin baş verəcəyinin, məsələn, işin nə vaxt bitəcəyinin təxmini.","also":["proqnozlar","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metrika","text":"Zamanla ölçüb izlədiyin hər şey, məsələn, səhifə ziyarətləri və ya düzəlişin nə qədər çəkməsi.","also":["metrikalar","metric","metrics"]},{"id":"feedback","g":"plan","word":"Rəy (feedback)","text":"İnsanların sənin işin barədə dedikləri, yaxşı və pis. Onu tez-tez və erkən almaq Agile-in ürəyidir.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Hələ planlaşdırılmamış fikirlərin və işlərin gözləmə siyahısı, ən vacibi yuxarıda. Orada heç nə «Görüləcək»ə keçməyincə üzərində işlənmir."},{"id":"sprint","g":"agile","word":"Sprint","text":"Məqsədi və bitiriləcək razılaşdırılmış kart dəsti olan qısa, sabit iş müddəti (çox vaxt bir-iki həftə, heç vaxt aydan çox yox).","also":["sprintlər"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Qısa gündəlik yoxlama: hər üzv nə etdi, sonra nə edəcək və nə mane olur. Scrum-da buna gündəlik scrum deyilir.","also":["standup","stand-ups","daily scrum","daily stand-up","gündəlik scrum"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Kartların lövhənin sütunları boyu (məsələn, Görüləcək, İcrada, Hazırdır) keçdiyi və komandanın eyni anda icrada olanı məhdudlaşdırdığı iş üsulu; iş axıcı qalsın deyə."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP — work in progress, yəni «icrada olan iş» deməkdir. WIP limiti bir sütunda eyni anda ola biləcək ən çox kart sayıdır; komanda yenisinə başlamazdan əvvəl başladığını bitirsin deyə.","also":["WIP"]},{"id":"dod","g":"agile","word":"Tamamlandı tərifi","text":"Kart sizə verilməzdən əvvəl “bitdi”nin nə demək olduğunu göstərən qısa komanda siyahısı, məsələn sınanıb və izah olunub. Onun əkizi, Hazır tərifi, kartın başlamaq üçün nə vaxt kifayət qədər aydın olduğunu deyir.","also":["Definition of Ready","DoD","DoR","Hazırlıq tərifi"]},{"id":"retro","g":"agile","word":"Retro","text":"Komandanın necə işlədiyinə müntəzəm geriyə baxış; növbəti dəfə daha yaxşı etmək üçün bir-iki şey razılaşdırmaq. Retrospektivin qısası. AI-gile-də retro komandanın iş qaydalarında dəyişiklik təklif edir və sən «Go» və ya «Hələ yox» deyirsən.","also":["retrolar","retrospektiv"]},{"id":"swarm","g":"agile","word":"Sürü","text":"Hamı köməyə: çoxlu adam başqa işi buraxıb bir təcili məsələni həll olunana qədər birlikdə düzəldir. AI-gile-də hər komanda bir layihədə kömək edir, digər layihələr isə bu vaxt gözləyir.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrum-da komandanın yaxşı işləməsinə kömək edən adam: onlara mane olanı aradan qaldırır, görüşləri yolda saxlayır və heç kimə əmr vermədən yaxşı vərdişlər aşılayır. AI-gile-də Lead Scrum Master ilişib qalan kartları görür, komandaları dürtür və hər layihədə nələrin gözlədiyini sənə xatırladır.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (çevik yanaşma)","text":"Kiçik addımlarla işləmək üsulu: azca qur, real nəticələri tez-tez göstər, insanların dediklərindən öyrən və hər şeyi əvvəlcədən planlaşdırmaq əvəzinə planı yolda dəyiş.","also":["Agile development","agile ways of working","çevik inkişaf"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto (Çevik Manifest)","text":"2001-ci ildə proqram yaradıcıları tərəfindən yazılmış qısa bəyanat. İnsanları, işləyən nəticələri, müştərilərlə yaxın işi və dəyişikliyə cavab verməyi ağır planların və kağız işlərinin qarşısına qoyur.","also":["Manifesto for Agile Software Development","Agile Manifesti"]},{"id":"waterfall","g":"agile","word":"Waterfall (şəlalə modeli)","text":"Köhnə iş üsulu: əvvəl hər şeyi planlaşdır, sonra hamısını qur, sonra hamısını test et, mərhələ-mərhələ. Gec dəyişiklik çətin və bahalıdır.","also":["waterfall model","şəlalə modeli"]},{"id":"iteration","g":"agile","word":"İterasiya","text":"Nəyisə qurmaq, yoxlamaq və yaxşılaşdırmaq üçün bir dövrə. Agile iş bunların zəncirindən ibarətdir, sprint isə onlardan biridir.","also":["iterasiyalar","iteration"]},{"id":"increment","g":"agile","word":"İnkrement","text":"Sprintdə və ya iş dövründə məhsula əlavə olunan, əvvəlkilərlə uyğun gələn yeni işlək hissə.","also":["inkrementlər","increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Məşhur Agile iş üsulu: kiçik komanda qısa sprintlərlə məqsədə doğru işləyir; müəyyən rollar və planlamaq, yoxlamaq, yaxşılaşdırmaq üçün bir neçə müntəzəm görüş var."},{"id":"scrumteam","g":"agile","word":"Scrum komandası","text":"Scrum-da işi görən kiçik qrup: məhsul sahibi, Scrum Master və developerlər.","also":["Scrum komandaları","Scrum team"]},{"id":"ceremonies","g":"agile","word":"Scrum tədbirləri","text":"Scrum-un müntəzəm görüşləri: sprint planlaşdırması, gündəlik scrum, sprint icmalı və retro. Çoxları onlara mərasim (ceremonies) deyir.","also":["mərasimlər","Scrum ceremonies","ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planlaşdırması","text":"Sprintin əvvəlindəki görüş: komanda sprintin nə üçün vacib olduğunu, hansı kartları götürəcəyini və necə başlayacağını razılaşdırır.","also":["planlaşdırma görüşü","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Sprint məqsədi","text":"Sprintin nə üçün olduğunu deyən bir cümlə. Məqsədə çatıldığı müddətcə kiçik tapşırıqlar yolda dəyişə bilər.","also":["sprint məqsədləri","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog-u","text":"Cari sprint üçün seçilmiş kartlar və komandanın onları yerinə yetirmə planı.","also":["sprint backlog","sprint backlog-ları"]},{"id":"productbacklog","g":"agile","word":"Məhsul backlog-u","text":"Məhsul üçün qurula biləcək hər şeyin tam sıralı siyahısı, ən vacibi yuxarıda. Öyrəndikcə dəyişməyə davam edir.","also":["product backlog","məhsul backlog-ları"]},{"id":"productgoal","g":"agile","word":"Məhsul məqsədi","text":"Məhsulun can atdığı daha böyük nəticə; komandaya növbəti addımı seçməkdə kömək edir.","also":["məhsul məqsədləri","product goal"]},{"id":"refinement","g":"agile","word":"Backlog-un dəqiqləşdirilməsi","text":"Kartları səliqəyə salmaq, bölmək, sıralamaq və ətraflı etmək üçün backlog-a müntəzəm baxmaq; beləliklə onlar götürülməyə hazır olur. Backlog grooming də deyilir.","also":["backlog grooming","refinement","backlog refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint icmalı","text":"Sprintin sonunda komandanın bitirdiyini göstərdiyi və insanların fikrini dinlədiyi görüş; növbətinin nə olacağını qərara almaq üçün.","also":["sprint icmalları","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Bitmiş işi, işləyən halda, canlı olaraq onu istəyən adamlara göstərmək.","also":["demolar","nümayiş"],"noTip":1},{"id":"timebox","g":"agile","word":"Vaxt çərçivəsi (timebox)","text":"Bir şey üçün ayrılmış sabit vaxt. Bitəndə, hər şey tamamlanmasa da, dayanırsan.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity (komanda sürəti)","text":"Komandanın bir sprintdə adətən bitirdiyi iş miqdarı; gələn dəfə nə qədər götürəcəyini planlamaq üçün. İnsanların nə qədər çox çalışdığının balı deyil.","also":["velocity","komanda sürəti"]},{"id":"capacity","g":"agile","word":"Tutum (capacity)","text":"Komandanın tətillər və digər işlərdən sonra bir dövrdə götürə biləcəyi iş miqdarı.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown qrafiki","text":"Sprintdə qalan işin gündən-günə azalmasını göstərən qrafik. Xətt düz qalırsa, nəsə ilişib.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Burnup qrafiki","text":"Bitmiş işin zamanla artmasını planlaşdırılan cəmin yanında göstərən qrafik; nə vaxt çatacağını görəsən deyə.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban lövhəsi","text":"Lövhənin özü: işin hər mərhələsi üçün bir sütun, kartlar onların üzərindən keçir.","also":["Kanban lövhələri","Kanban board"]},{"id":"pullsys","g":"agile","word":"Çəkmə sistemi (pull system)","text":"Yeni işin yalnız kiminsə onu götürməyə yeri olanda başladığı iş üsulu; işi onsuz da dolu olanın üstünə yığmaq əvəzinə.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Axın (flow)","text":"İşin lövhə boyu nə qədər rahat hərəkət etməsi. Yaxşı axın o deməkdir ki, kartlar yığılmır, irəliləyir.","also":["flow","işin axını"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (ümumi müddət)","text":"Kiminsə nəyisə istəməsindən onun bitməsinə qədər keçən vaxt.","also":["lead time","lead times","ümumi müddət"]},{"id":"cycletime","g":"agile","word":"Cycle time (icra müddəti)","text":"Kartın üzərində işin həqiqətən başlamasından bitməsinə qədər keçən vaxt.","also":["cycle time","cycle times","icra müddəti"]},{"id":"throughput","g":"agile","word":"Buraxılış qabiliyyəti (throughput)","text":"Həftədə və ya hər hansı verilmiş vaxtda neçə kartın bitməsi.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Dar boğaz (bottleneck)","text":"İşin yığıldığı və arxasındakı hər şeyi ləngidən tək mərhələ, şüşənin dar boğazı kimi.","also":["dar boğazlar","bottleneck"]},{"id":"swimlane","g":"agile","word":"Swimlane (üfüqi zolaq)","text":"Lövhə boyunca bir növ kartları qruplaşdıran sətir, məsələn, təcili iş və ya bir komandanın kartları.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (qənaətcil yanaşma)","text":"İsrafı (müştəriyə kömək etməyən hər şeyi) kəsən və işi axıcı saxlayan iş üsulu."},{"id":"waste","g":"agile","word":"İsraf (waste)","text":"Lean-də səy tələb edən, amma müştəriyə kömək etməyən hər şey, məsələn, gözləmək, işi təkrar etmək və ya heç kimin istifadə etmədiyi şeylər qurmaq.","noTip":1},{"id":"kaizen","g":"agile","word":"Fasiləsiz təkmilləşmə","text":"Kiçik müntəzəm dəyişikliklərlə daim bir az yaxşılaşmaq, sonra kömək edib-etmədiyini yoxlamaq. Retro bunun yollarından biridir. Kaizen də deyilir.","also":["kaizen","davamlı təkmilləşmə","continuous improvement"]},{"id":"selforg","g":"agile","word":"Özünütəşkil edən komanda","text":"İşi necə görəcəyinə addım-addım deyilmək əvəzinə özü qərar verən komanda.","also":["özünütəşkil","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Çoxfunksiyalı komanda","text":"İşi özü bitirmək üçün lazım olan bütün bacarıqlara, məsələn, dizayn, qurma və test, malik komanda.","also":["cross-functional","funksiyalararası komanda"]},{"id":"spike","g":"agile","word":"Spike (araşdırma tapşırığı)","text":"Əsl işə girişməzdən əvvəl suala cavab tapmaq üçün qısa, vaxtı məhdud araşdırma.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Təkrar iş (rework)","text":"Birinci dəfə düzgün olmadığı üçün işi yenidən görmək.","also":["rework","yenidən işləmə"]},{"id":"safe","g":"agile","word":"Miqyaslanmış Agile (SAFe)","text":"Böyük təşkilatda çoxlu komandalar arasında Agile-dən istifadə yolları. SAFe (Scaled Agile Framework) tanınmış nümunələrdən biridir.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Layihənin kod qovluğu, commit-lərin tam tarixçəsi ilə birlikdə. Kompüterində, GitHub-da və ya hər ikisində ola bilər.","also":["repozitoriya"]},{"id":"branch","g":"build","word":"Branch","text":"Kodda ayrıca iş xətti, beləliklə əsas versiyaya toxunmadan dəyişiklik etmək olar.","also":["branch-lər"]},{"id":"commit","g":"build","word":"Commit","text":"Kodun nəyin dəyişdiyinə dair qısa qeydlə saxlanmış anlıq görüntüsü. Həmişə ona qayıtmaq olar.","also":["commit-lər"]},{"id":"push","g":"build","word":"Push","text":"Saxladığın görüntüləri (commit-ləri) bu kompüterdən GitHub kimi onlayn ortaq surətə göndərmək; beləliklə onların ehtiyatı olur və başqaları götürə bilir."},{"id":"merge","g":"build","word":"Merge","text":"Bir branch-dakı dəyişiklikləri digərinə, adətən əsas versiyaya geri birləşdirmək."},{"id":"pr","g":"build","word":"Pull request","text":"Branch-dakı dəyişikliklərin yoxlanıb əsas versiyaya birləşdirilməsini istəmək. Bəzi saytlar buna merge request deyir.","also":["PR","PRs","merge request","pull request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodun nə etdiyini dəyişmədən səliqəyə salmaq: daha kiçik fayllar, daha aydın adlar, daha az təkrar."},{"id":"bug","g":"build","word":"Bug","text":"Olmalı olduğu kimi işləməyən şey.","also":["buglar"]},{"id":"peerreview","g":"build","word":"Həmkar yoxlaması","text":"İkinci cüt göz: müəllifdən başqa biri işi sənə çatmazdan əvvəl yoxlayır; beləliklə daha az səhv keçir. AI-gile-də hər kartı başqa bir AI yoxlayır.","also":["kod yoxlaması","peer review","code review"]},{"id":"code","g":"build","word":"Kod","text":"Kompüterə nə edəcəyini deyən yazılı təlimatlar. Mənbə kodu da deyilir.","also":["mənbə kodu","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Proqramlaşdırma dili","text":"Kod yazmaq üçün dil, məsələn, JavaScript, Python və ya Java. Fərqli dillər fərqli işlərə yarayır.","also":["proqramlaşdırma dilləri","programming language"]},{"id":"developer","g":"build","word":"Developer (proqramçı)","text":"Kod yazan və dəyişən adam. Proqramçı və ya proqram mühəndisi də deyilir.","also":["developer","developerlər","proqramçı","proqramçılar","software engineer"]},{"id":"software","g":"build","word":"Proqram təminatı","text":"Kompüter və telefonlarda işləyən proqramlar; maşınların özündən (hardware, yəni avadanlıq) fərqli olaraq.","noTip":1},{"id":"app","g":"build","word":"Tətbiq (app)","text":"Application sözünün qısası: insanların nəyisə etmək üçün telefonda, kompüterdə və ya brauzerdə istifadə etdiyi proqram.","also":["app","apps","application","applications","tətbiqlər"],"noTip":1},{"id":"webapp","g":"build","word":"Veb tətbiq","text":"Brauzerdə işləyən tətbiq, ona görə heç nə quraşdırmaq lazım deyil.","also":["web app","web apps","web application","veb tətbiqlər"]},{"id":"frontend","g":"build","word":"Front end (ön hissə)","text":"Tətbiqin gördüyün və kliklədiyin hissəsi: ekranlar, düymələr və yazılar, çox vaxt brauzerində.","also":["front-end","frontend","ön hissə"]},{"id":"backend","g":"build","word":"Back end (arxa hissə)","text":"Tətbiqin pərdəarxası hissəsi: məlumatı saxlayır və nəyisə klikləyəndə işi görür, məsələn, parolunu yoxlayır.","also":["back-end","backend","arxa hissə"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Həm front end, həm də back end üzərində işləmək.","also":["full-stack"]},{"id":"ui","g":"build","word":"İstifadəçi interfeysi (UI)","text":"İnsanın ekranda gördüyü və istifadə etdiyi şey: yerləşmə, düymələr, menyular və yazılar.","also":["UI","user interface","interfeys"]},{"id":"ux","g":"build","word":"İstifadəçi təcrübəsi (UX)","text":"Nəyindənsə istifadənin necə hiss olunması: asan, aydın və xoş, yoxsa qarışıq və yavaş.","also":["UX","user experience","istifadəçi təcrübəsi"]},{"id":"accessibility","g":"build","word":"Əlçatanlıq (a11y)","text":"Şeyləri hamı üçün, o cümlədən pis görənlər, siçandan istifadə edə bilməyənlər və ya ekran oxuyucudan istifadə edənlər üçün yararlı etmək.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Adaptiv dizayn (responsive)","text":"Səhifələrin telefondan böyük monitora qədər hər ekran ölçüsünə uyğunlaşıb yaxşı işləməsini təmin etmək.","also":["responsive design","adaptiv"]},{"id":"designsys","g":"build","word":"Dizayn sistemi","text":"Rənglərin, şriftlərin, düymələrin və qaydaların ortaq dəsti; beləliklə hər ekran eyni görünür və eyni davranır.","also":["dizayn sistemləri","design system"]},{"id":"architecture","g":"build","word":"Arxitektura","text":"Sistemin ümumi forması: əsas hissələrin nələr olduğu və bir-biri ilə necə danışdığı."},{"id":"database","g":"build","word":"Verilənlər bazası (DB)","text":"Məlumatın nizamlı saxlandığı yer; tətbiqin oxuya və dəyişə biləcəyi çox güclü cədvələ bənzəyir.","also":["database","databases","DB","məlumat bazası"]},{"id":"schema","g":"build","word":"Baza sxemi (schema)","text":"Bazanın quruluşu: hansı məlumat cədvəllərinin olduğu və hər birinə nəyin yazıldığı.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Structured query language-in qısası: bir çox bazadan məlumat istəmək və ya onu dəyişmək üçün işlədilən dil.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Məlumat (data)","text":"Kompüterin saxladığı məlumat, məsələn, adlar, sifarişlər və ya parametrlər.","also":["data","dataset","datasets","verilənlər"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Həmişə açıq olan və digər kompüterlərin sorğularına cavab verən kompüter, məsələn, sayta girəndə sənə veb səhifəni göndərir.","also":["serverlər","servers"]},{"id":"client","g":"build","word":"Müştəri tərəf (client)","text":"Serverdən nəyisə istəyən tərəf, adətən brauzerin və ya tətbiqin. Biznesdə isə sadəcə müştəri deməkdir.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Application programming interface-in qısası: bir proqramın digərinə verə biləcəyi sorğuların hazır menyusu, məsələn, hava xidmətindən bugünkü proqnozu istəmək kimi.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (son nöqtə)","text":"API menyusunun bir bəndi: proqramın nəyisə almaq və ya göndərmək üçün çağıra biləcəyi veb ünvan.","also":["endpoint","endpoints","son nöqtə"]},{"id":"integration","g":"build","word":"İnteqrasiya","text":"İki sistemi birlikdə işləsin deyə qoşmaq, məsələn, mağazanın sifarişləri mühasibat proqramına göndərməsi kimi.","also":["inteqrasiyalar","integration"]},{"id":"webhook","g":"build","word":"Webhook","text":"Bir sistemin nəsə baş verən kimi, məsələn, «ödəniş alındı», özbaşına digərinə göndərdiyi mesaj.","also":["webhooks","vebhuk"]},{"id":"library","g":"build","word":"Kitabxana (library)","text":"Başqasının yazdığı, özün yazmaq əvəzinə təkrar istifadə edə biləcəyin hazır kod.","also":["library","libraries","kitabxanalar"],"noTip":1},{"id":"framework","g":"build","word":"Framework (freymvork)","text":"Tətbiq qurmaq üçün hazır quruluş; kodun düzülüşünün çox hissəsini müəyyən edir, doldurduğun ev karkası kimi.","also":["framework","frameworks","freymvork"]},{"id":"sdk","g":"build","word":"Proqram hazırlama dəsti (SDK)","text":"Bir platforma və ya xidmət üçün proqram qurmaq üçün alətlər, kod və nümunələr qutusu.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Proqram asılılığı","text":"Kodunun işləməsi üçün lazım olan kitabxana və ya alət. Onları yenilənmiş saxlamaq təhlükəsizlik üçün vacibdir.","also":["proqram asılılıqları","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Paket","text":"Layihədə quraşdırıb istifadə edə biləcəyin hazır kod dəsti.","also":["paketlər","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Paket meneceri","text":"Kodunun asılı olduğu paketləri gətirən və yeniləyən alət. npm geniş yayılmışdır.","also":["paket menecerləri","package manager","npm"]},{"id":"git","g":"build","word":"Git","text":"Kod dəyişikliklərinin tarixçəsini commit və branch şəklində saxlamaq üçün ən geniş istifadə olunan alət."},{"id":"github","g":"build","word":"GitHub","text":"Git repolarını onlayn saxlayan sayt; komandalar kodu bölüşsün, dəyişikliklərə baxsın və işi izləsin deyə."},{"id":"vcs","g":"build","word":"Versiya nəzarəti","text":"Fayllarda hər dəyişikliyin tam tarixçəsini saxlamaq; kimin nəyi dəyişdiyini görmək və lazım olsa geri qayıtmaq üçün. Git bunu edir.","also":["version control","source control","version control system","mənbə nəzarəti"]},{"id":"clone","g":"build","word":"Clone (klonlamaq)","text":"Repo-nun tarixçəsi ilə birlikdə kompüterində öz tam surətini çıxarmaq.","also":["clone","cloned","cloning","klon"]},{"id":"pull","g":"build","word":"Pull (çəkmək)","text":"Ən son commit-ləri ortaq surətdən (məsələn, GitHub) kompüterinə gətirmək. Push-un əksi.","also":["pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Əsas branch","text":"Hamının üzərində işlədiyi rəsmi kod versiyası, çox vaxt main və ya master adlanır.","also":["main branch","master branch","əsas şaxə"]},{"id":"conflict","g":"build","word":"Merge konflikti","text":"İki dəyişiklik eyni sətirlərə fərqli yollarla toxunanda kompüter onları birləşdirə bilmir və insan seçməlidir.","also":["merge conflict","merge conflicts","birləşmə konflikti"]},{"id":"diff","g":"build","word":"Diff (fərq)","text":"İki versiya arasında dəqiq nəyin dəyişdiyini göstərən görünüş: əlavə olunan və silinən sətirlər.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Başqasının repo-sunun öz surətin; onunkuna toxunmadan dəyişə bilərsən.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"Skript","text":"Bir işi özü görən qısa proqram, məsələn, faylları səliqəyə salmaq və ya tətbiqi işə salmaq.","also":["script","scripts","skriptlər"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Kodu işə hazır hala gətirmək və ya hazır olan nəticənin özü.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilyasiya (compile)","text":"İnsanların yazdığı kodu kompüterin birbaşa işlədə biləcəyi formaya çevirmək.","also":["compile","compiler","kompilyasiya"]},{"id":"cli","g":"build","word":"Komanda sətri (CLI)","text":"Klikləmək əvəzinə kompüterə təlimatları yazdığın mətn pəncərəsi. Terminal da deyilir.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Konfiqurasiya (config)","text":"Proqramın necə davranacağına nəzarət edən parametrlər; asan dəyişsin deyə koddan ayrı saxlanılır.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Mühit dəyişəni","text":"Proqram başlayanda ona verilən parametr; ünvanlar və ya parollar koda yazılmasın deyə tez-tez bundan istifadə olunur.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging (xəta axtarışı)","text":"Nəyinsə niyə işləmədiyini axtarıb tapmaq və düzəltmək.","also":["debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Cütlükdə proqramlaşdırma","text":"İki nəfərin (və ya insan və AI) eyni kod üzərində birlikdə işləməsi: biri yazır, o biri yoxlayır.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Sənədləşmə (docs)","text":"Nəyinsə necə işlədiyini və ya necə istifadə olunduğunu izah edən yazılı izahatlar.","also":["documentation","docs","dokumentasiya"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Repo-da oxunacaq ilk fayl: layihənin nə olduğu və onu necə işə salmaq olar.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Köhnə sistem (legacy)","text":"Hələ də işlədilən, dəyişməsi çətin köhnə sistem; çox vaxt onu başa düşən az adam qaldığı üçün.","also":["legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Texniki borc","text":"İndi vaxta qənaət edən, amma sonrakı dəyişiklikləri yavaşladan qısa yollar; faiz yığılan borc kimi. Refaktorinq onu ödəyir.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Nəyinsə düzgün işlədiyinin yoxlanması. Bəzi testləri kompüter kod hər dəyişəndə özü işlədir; digərləri isə sənin qəbul etməzdən əvvəl bitmiş kartı sınamandır.","also":["testlər"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Quality assurance-ın qısası: işin canlıya çıxmazdan əvvəl düzgün olduğuna əmin olmaq üçün görülən hər şey. AI-gile-də bu avtomatik yoxlamalar deməkdir: QA qırmızıdırsa, nəsə alınmayıb və bu düzəlməyincə canlıya çıxa bilməz.","also":["keyfiyyət yoxlamaları","keyfiyyətin təminatı","quality checks"]},{"id":"testpile","g":"test","word":"Sınaq yığını","text":"Sizin sınamağınızı gözləyən bitmiş kartlar, bir-birinin ardınca. Birini qəbul edin və ya qeydlə geri qaytarın, növbəti gəlir.","also":["sınaq yığınları","test pile"]},{"id":"autotest","g":"test","word":"Avtomatik test","text":"Kod hər dəyişəndə kompüterin özbaşına işlətdiyi yoxlama; səhvləri erkən tutmaq üçün.","also":["avtomatik testlər","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Əl ilə test","text":"İnsanın işi lazım olduğu kimi davranıb-davranmadığını görmək üçün əllə sınaması.","also":["əl testi","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test (vahid testi)","text":"Kodun tək bir kiçik hissəsinin ayrılıqda kiçik avtomatik yoxlanması.","also":["unit test","unit tests","vahid testi"]},{"id":"integtest","g":"test","word":"İnteqrasiya testi","text":"Bir neçə hissənin tək-tək yox, birlikdə düzgün işlədiyini yoxlayan test.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Başdan-sona test (E2E)","text":"Real istifadəçi kimi başdan sona hərəkət edən test, məsələn, qeydiyyat, alış və ödəniş.","also":["E2E","end-to-end test","end-to-end tests"]},{"id":"uat","g":"test","word":"İstifadəçi qəbul testi (UAT)","text":"İşi istəyən adamlar onu özləri sınayır və ehtiyaclarını ödəyib-ödəmədiyini deyirlər. AI-gile-dəki sınaq yığını bunun bir növüdür.","also":["UAT","acceptance testing","qəbul testi"]},{"id":"regression","g":"test","word":"Reqressiya","text":"Əvvəllər işləyən, amma dəyişiklikdən sonra sınan şey. Reqressiya testləri köhnə şeylərin hələ işlədiyini yoxlayır.","also":["regression","regressions","regression test","regression tests","regression testing","reqressiya testi"]},{"id":"smoke","g":"test","word":"Smoke test (tüstü testi)","text":"Əsas şeylərin ümumiyyətlə işlədiyini yoxlayan çox sürətli yoxlama, məsələn, dəyişiklik canlıya çıxan kimi. Alınmasa, dayan və bax.","also":["smoke test","smoke tests","tüstü testi"]},{"id":"exploratory","g":"test","word":"Araşdırmalı test (exploratory testing)","text":"Planlı yoxlamaların qaçıracağı problemləri tapmaq üçün məhsulu sərbəst sınamaq və müxtəlif yollarla qurcalamaq.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test ssenarisi (test case)","text":"Sınanacaq bir yazılı ssenari: addımlar və nə baş verməli olduğu.","also":["test case","test cases","test halı"]},{"id":"coverage","g":"test","word":"Test əhatəsi (coverage)","text":"Kodun nə qədərinin avtomatik testlərlə yoxlandığı. Çox olması adətən daha etibarlıdır, amma yüksək əhatə təkbaşına yaxşı işlədiyini sübut etmir.","also":["code coverage","kod əhatəsi"]},{"id":"testdata","g":"test","word":"Test məlumatı","text":"Test zamanı istifadə olunan uydurma nümunə məlumat; beləliklə heç bir real adamın şəxsi məlumatı açılmır.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Sərhəd hal (edge case)","text":"Hədlərdəki qeyri-adi vəziyyət, məsələn, boş forma və ya apostrof olan ad; burada çox vaxt şeylər sınır.","also":["edge case","edge cases","sərhəd halları"]},{"id":"happypath","g":"test","word":"Xoşbəxt yol (happy path)","text":"Hər şeyin düz getdiyi adi yol. Yaxşı test işlərin pis getdiyi yolları da sınayır."},{"id":"perftest","g":"test","word":"Performans testi","text":"Nəyinsə nə qədər sürətli olduğunu və yük altında nə qədər yaxşı tab gətirdiyini yoxlamaq.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Yük testi","text":"Çoxlu adam eyni vaxtda istifadə edəndə sistemin necə tab gətirdiyini yoxlamaq.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Təhlükəsizlik testi","text":"Kiminsə sistemdən sui-istifadə etməsinə və ya görməməli olduğunu görməsinə imkan verə biləcək zəiflikləri axtarmaq.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Əlçatanlıq testi","text":"Müxtəlif imkanları olan insanların, o cümlədən ekran oxuyucu ilə və ya yalnız klaviatura ilə, məhsuldan istifadə edə bildiyini yoxlamaq.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Koddakı ehtimal olunan səhvləri və səliqəsiz üslubu görən avtomatik yoxlama; proqramlar üçün orfoqrafiya yoxlayıcısı kimi.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statik analiz","text":"Kodu işə salmadan, onu avtomatik oxuyaraq problemlər üçün yoxlamaq.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Qeyri-sabit test (flaky)","text":"Bəzən keçən, bəzən aydın səbəb olmadan keçməyən test; ona tam etibar etmək olmur.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Təkrar yaratmaq (repro)","text":"Xətanı eyni addımları izləyərək qəsdən yenidən yaratmaq ki, onu öyrənib düzəltmək mümkün olsun. O addımları yazmaq xəta hesabatının ən faydalı hissəsidir.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Ciddilik dərəcəsi","text":"Problemin təsirinin nə qədər pis olduğu: kiçik narahatlıqdan hər şeyin dayanmasına qədər.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Proqramın yeni versiyasını onu işlədən kompüterlərə, məsələn, test surətinə və ya canlı xidmətə köçürmək."},{"id":"release","g":"change","word":"Buraxılış","text":"Birlikdə canlıya çıxan, adı olan bitmiş iş paketi, nəyin dəyişdiyi barədə qısa qeydlərlə. 🚀 Buraxılışlar qeydləri bitmiş kartlardan yazır.","also":["buraxılışlar","release"]},{"id":"rollback","g":"change","word":"Geri qaytarma","text":"Yeni versiya problem çıxaranda işləyən sonuncu versiyaya qayıtmaq. AI-gile-də «Geri qaytar» hər dəyişikliyə yazılmış geri alma addımlarını bir yoxlama siyahısında toplayır.","also":["geri qaytar","rollback","roll back"]},{"id":"live","g":"change","word":"Canlı","text":"İnsanların istifadə etdiyi əsl versiya, sınaq üçün olan nüsxədən fərqli olaraq. Developerlər buna production (prod) da deyirlər.","also":["prod","production","canlı mühit","live"],"noTip":1},{"id":"change","g":"change","word":"Dəyişiklik","text":"İnsanların güvəndiyi bir şeydə planlaşdırılmış dəyişiklik, əvvəlcə yazılır: nə, niyə, risk, nə vaxt və necə geri qaytarılacaq. 🔀 Dəyişiklik təklif et ilə birini başladın.","also":["dəyişikliklər","dəyişiklik sorğusu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Pis gedə biləcək bir şey, nə qədər ehtimal olunduğuna və nə qədər pis olacağına görə xal alır. ⚠️ Risklər onları bir siyahıda saxlayır, ən yüksək xal əvvəldə, hər birinin yenidən baxmaq üçün tarixi var.","also":["risklər","risk reyestri"]},{"id":"chgwin","g":"change","word":"Dəyişiklik pəncərəsi","text":"Dəyişikliklərin canlıya çıxa biləcəyi vaxtlar, məsələn sakit bir çərşənbə axşamı, axşam saatlarında. Pəncərədən kənarda dəyişiklik kartı bitirilə bilməz, təcili hal olmadıqca.","also":["dəyişiklik pəncərələri","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Dəyişiklik canlıya çıxmazdan əvvəlki son yoxlama: təsdiq etməli olan hər adam «Go» (davam) və ya «No go» (dayan) deyir. Yalnız hamı «Go» deyəndə irəli gedir.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Təsdiq","text":"İş başlamazdan əvvəl “bəli” gözləmək. Dostun təklif etdiyi kart və ya dəyişiklik siz təsdiqləyənə və ya rədd edənə qədər ✅ Təsdiqlər bölməsində gözləyir.","also":["təsdiqlər","approval"]},{"id":"quiettime","g":"change","word":"Sakit vaxt","text":"Heç nəyin canlıya çıxmadığı vaxt aralığı, məsələn, canlı yayım, demo və ya gecə zamanı. Komandalar işləməyə və test etməyə davam edir, amma canlıya çıxmaq bu vaxt bitənə qədər gözləyir. Başqa yerlərdə buna change freeze (dəyişiklik dondurulması) deyilir.","also":["sakit vaxtlar","dəyişiklik dondurulması","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Proqramı quran adamlarla onu işlədən adamların vahid komanda kimi işlədiyi, çoxlu avtomatlaşdırma olan iş üsulu; dəyişikliklər tez-tez və təhlükəsiz canlıya çıxsın deyə."},{"id":"cicd","g":"change","word":"CI/CD (fasiləsiz inteqrasiya və çatdırma)","text":"Hamının dəyişiklikləri tez-tez əsas versiyaya birləşdirilir və hər dəfə avtomatik yoxlanılır (fasiləsiz inteqrasiya); beləliklə proqram həmişə bir düymə ilə canlıya çıxmağa hazırdır (fasiləsiz çatdırma).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","fasiləsiz inteqrasiya"]},{"id":"contdeploy","g":"change","word":"Fasiləsiz yerləşdirmə","text":"Fasiləsiz çatdırmadan bir addım irəli: yoxlamalardan keçən hər dəyişiklik özbaşına canlıya çıxır, basılacaq düymə yoxdur.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (konveyer)","text":"Dəyişikliyin canlıya gedən yolunda keçdiyi avtomatik addımlar silsiləsi, məsələn, yığma, test, sonra yerləşdirmə.","also":["pipeline","pipelines","konveyer"]},{"id":"environment","g":"change","word":"Mühit (environment)","text":"Sistemin bir məqsəd üçün ayrıca surəti, məsələn, biri qurmaq, biri test etmək üçün, biri də canlı olan.","also":["environment","environments","mühitlər"],"noTip":1},{"id":"devenv","g":"change","word":"Development mühiti","text":"Developerin işlədiyi surət, çox vaxt öz kompüterində, burada nəyisə sındırmaq heç kimə zərər vurmur.","also":["dev environment","development environment","inkişaf mühiti"]},{"id":"testenv","g":"change","word":"Test mühiti","text":"Yalnız test üçün istifadə olunan ayrıca sistem surəti; real xidmətə toxunulmasın deyə.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Staging (hazırlıq mühiti)","text":"Dəyişiklik canlıya çıxmazdan əvvəl son yoxlama üçün canlı kimi qurulmuş sonuncu surət.","also":["staging","staging environment","hazırlıq mühiti"]},{"id":"artifact","g":"change","word":"Build artefaktı","text":"Yığmanın hazırladığı fayl və ya paket; saxlanılmağa, yoxlanılmağa və ya canlıya qoyulmağa hazırdır.","also":["build artifact","build artifacts","artefakt"]},{"id":"hotfix","g":"change","word":"Hotfix (təcili düzəliş)","text":"Vacib bir şey sındığı üçün adi planın kənarında tez canlıya qoyulan təcili düzəliş.","also":["hotfix","hotfixes","təcili düzəliş"]},{"id":"patch","g":"change","word":"Patch (yamaq)","text":"Xətanı düzəldən və ya təhlükəsizlik boşluğunu bağlayan kiçik yeniləmə. Təhlükəsizlik yamaqlarını tez tətbiq etmək vacibdir.","also":["patch","patches","security patch","security patches","yamaq","təhlükəsizlik yamağı"]},{"id":"version","g":"change","word":"Versiya nömrəsi","text":"2.4.1 kimi etiket; hansı buraxılışın səndə olduğunu deyir. Çox vaxt böyük dəyişikliklər üçün birinci, kiçik düzəlişlər üçün sonuncu rəqəm dəyişir.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Buraxılış qeydləri","text":"Buraxılışda nəyin dəyişdiyinin, düzəlişlərin və məlum məhdudiyyətlərin, onu istifadə edənlər üçün qısa sadə siyahısı. Changelog da deyilir.","also":["release notes","changelog","change log","dəyişiklik jurnalı"]},{"id":"flag","g":"change","word":"Feature flag (funksiya açarı)","text":"Funksiya üçün aç-bağla açarı; beləliklə yeni iş gizli şəkildə canlıya çıxa və yeni buraxılış olmadan açıla (ya da yenidən bağlana) bilər.","also":["feature flag","feature flags","feature toggle","feature toggles","funksiya açarı"]},{"id":"rollfwd","g":"change","word":"Roll forward (irəli düzəliş)","text":"Pis buraxılışı köhnəyə qayıtmaq əvəzinə düzəldilmiş yeni versiyanı tez çıxararaq aradan qaldırmaq.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary buraxılışı","text":"Dəyişikliyi əvvəl kiçik qrup üçün, yaxşı görünəndən sonra hamı üçün canlıya çıxarmaq. Adını mədənçilərin yeraltına erkən xəbərdarlıq üçün apardığı kanareyka quşlarından alıb.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green yerləşdirmə","text":"Canlı sistemin iki surətini saxlayıb insanları birdən yenisinə keçirmək; pis getsə, dərhal geri qayıtmaq olar.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Dayanmasız yerləşdirmə","text":"Yeni versiyanı xidməti istifadəçilər üçün heç dayandırmadan canlıya qoymaq.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Dəyişikliyə imkan yaratma (change enablement)","text":"Dəyişikliklərin uğur qazanmasına kömək: riski ölçmək, düzgün razılıq almaq və yaxşı vaxt seçmək. Change management də deyilir.","also":["change management","dəyişiklik idarəetməsi"]},{"id":"cab","g":"change","word":"Dəyişiklik məsləhət şurası (CAB)","text":"Vacib dəyişikliklərə baxan və onların həyata keçirilib-keçirilməyəcəyini və nə vaxt keçiriləcəyini razılaşdıran qrup.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standart dəyişiklik","text":"Hər dəfə eyni sınanmış üsulla edilən az riskli dəyişiklik; ona görə əvvəlcədən təsdiqlənib.","also":["standart dəyişikliklər","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Normal dəyişiklik","text":"Həyata keçirilməzdən əvvəl yoxlanılmalı və təsdiqlənməli olan dəyişiklik.","also":["normal dəyişikliklər","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Təcili dəyişiklik","text":"Ciddi problemi düzəltmək və ya qarşısını almaq üçün dərhal edilməli olan dəyişiklik; təsdiq də ona uyğun daha sürətlidir.","also":["təcili dəyişikliklər","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Avtomatlaşdırma","text":"Təkrarlanan işi kompüterə özbaşına gördürmək; beləliklə daha sürətli olur və hər dəfə eyni cür görülür.","also":["automation","automated","avtomatlaşdırılmış"],"noTip":1},{"id":"infra","g":"change","word":"İnfrastruktur","text":"Proqramın üzərində işlədiyi maşınlar, şəbəkələr və xidmətlər.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Kod kimi infrastruktur (IaC)","text":"Serverlərini və ayarlarını kodla birlikdə saxlanan fayllarda təsvir etmək; beləliklə onları hər dəfə tam eyni cür yenidən qurmaq olur.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Bulud (cloud)","text":"Maşınlara özün sahib olmaq əvəzinə, böyük provayderdən internet üzərindən kompüter, yaddaş və xidmət icarəyə götürmək.","also":["cloud","the cloud","cloud computing","bulud","bulud hesablama"]},{"id":"provider","g":"change","word":"Bulud provayderi","text":"İnternet üzərindən hesablama icarəyə verən şirkət, məsələn, Amazon Web Services (AWS), Microsoft Azure və ya Google Cloud.","also":["cloud provider","cloud providers","bulud provayderləri"]},{"id":"hosting","g":"change","word":"Hostinq","text":"Tətbiqinin və ya saytının yaşadığı və insanların ona çata bilməsi üçün işlədiyi yer; adətən şirkətdən icarəyə götürülür.","also":["hosting","host"]},{"id":"domain","g":"change","word":"Domen adı","text":"İnsanların yazdığı veb ünvan, məsələn, example.com. Onu ilbəil icarəyə götürürsən, ona görə yenilənməlidir.","also":["domain name","domain names","domain","domen"]},{"id":"dns","g":"change","word":"DNS","text":"Domain name system-in qısası: internetin ünvan kitabçası; example.com kimi adı düzgün kompüterin ünvanına çevirir.","also":["domain name system"]},{"id":"container","g":"change","word":"Konteyner","text":"Tətbiqi və ona lazım olan hər şeyi saxlayan möhürlü paket; beləliklə o, hər kompüterdə eyni işləyir. Docker ən tanınmış alətdir.","also":["container","containers","Docker","konteynerlər"],"noTip":1},{"id":"vm","g":"change","word":"Virtual maşın (VM)","text":"Real kompüterin içində işləyən təqlidi kompüter; beləliklə bir böyük maşın çox maşın kimi işləyə bilir.","also":["VM","VMs","virtual machines","virtual machine"]},{"id":"serverless","g":"change","word":"Serverless (serversiz)","text":"Heç bir serverə özün baxmadan kod işlətmək: provayder onu lazım olanda işlədir, sən də istifadə etdiyin qədər ödəyirsən."},{"id":"lb","g":"change","word":"Yük balanslaşdırıcı (load balancer)","text":"Ziyarətçiləri bir neçə serverə paylayan şey; heç biri həddən çox yüklənməsin deyə.","also":["load balancer","load balancers","yük paylayıcı"]},{"id":"cache","g":"change","word":"Keş (cache)","text":"Son nəticələrin yaxında saxlanıldığı əlverişli yer; eyni şeyi yenidən gətirmək və ya hesablamaq lazım olmasın deyə. Onu təmizləmək köhnə görünən səhifələri düzəldə bilər.","also":["cache","caches","caching","cached","keş","keşləmə"]},{"id":"cdn","g":"change","word":"Məzmun çatdırma şəbəkəsi (CDN)","text":"Səhifələrinin və şəkillərinin surətlərini ziyarətçilərə yaxın saxlayan dünya miqyaslı server dəsti; tez yüklənsin deyə.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Miqrasiya","text":"Məlumatı və ya sistemləri köhnə qurğudan yenisinə köçürmək və ya bazanın düzülüşünü diqqətlə dəyişmək.","also":["migration","migrations","database migration"]},{"id":"service","g":"run","word":"Xidmət","text":"Qurduğunuz və insanların güvəndiyi bir şey, məsələn sayt və ya tətbiq, işləməyə davam etsin deyə qayğısına qalınır. “Bu layihə xidmətdir” qutusunu işarələyin və nə təklif etdiyini, kimin istifadə etdiyini və kimin növbədə olduğunu yazın.","also":["xidmətlər","service"]},{"id":"uptimepct","g":"run","word":"İşləmə vaxtı (uptime)","text":"Xidmətin vaxtın nə qədərində işlədiyi, adətən faiz kimi. 99,9% hələ də ayda təxminən 43 dəqiqə dayanmağa icazə verir.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"İşləmə yoxlaması","text":"Hər bir neçə dəqiqədən bir xidmətinizin hələ cavab verdiyini yoxlayan avtomatik yoxlama. Bir neçə dəfə ardıcıl alınmazsa, AI-gile özü insident kartı açır.","also":["uptime yoxlamaları","uptime checks"]},{"id":"statuspage","g":"run","word":"Status səhifəsi","text":"Xidmətin işləyib-işləmədiyini (yaşıl, narıncı və ya qırmızı) son yeniliklə göstərən açıq səhifə ki, istifadə edənlər soruşmaq əvəzinə baxa bilsinlər.","also":["status səhifələri","status page"]},{"id":"desk","g":"run","word":"Xidmət masası","text":"Xidmətinizdən istifadə edənlərin sualları və müraciətləri buraya gəlir. AI-gile hər birini sorğu, insident və ya fikir kimi çeşidləyir və artıq bildirilmiş bir şeyə bənzəyəndə bunu deyir.","also":["xidmət masaları","yardım masası","dəstək xidməti"]},{"id":"svcrequest","g":"run","word":"Xidmət sorğusu","text":"Nəyinsə xarab olduğunu bildirmək əvəzinə adi bir şey istəyən biri, məsələn yeni hesab və ya bir az kömək. Növbəsini gözləyir; insident birinci gedir.","also":["xidmət sorğuları"]},{"id":"incident","g":"run","word":"İnsident","text":"İndi istifadə edən insanlar üçün sınmış və ya düzgün işləməyən şey, məsələn, saytın dayanması və ya çox yavaş olması. 🔥 insident kartı növbəni qabaqlayır: onu yenidən işlək etmək birinci gəlir.","also":["insidentlər","incident"]},{"id":"major","g":"run","word":"Böyük insident","text":"Böyük insident: çox insan təsirlənib, ya da pul və ya məlumat risk altındadır. Bir düymə bütün komandaları onun üzərinə qoyur (sürü), növbədə olanı oyadır və hər 30 dəqiqədən bir status yeniləməsi istəyir.","also":["böyük insidentlər","major incident"]},{"id":"oncall","g":"run","word":"Növbətçilik","text":"Nəsə xarab olanda, hətta gecə də, cavab verən adam olmaq. Hər xidmətin öz insidentləri üçün ilk oyadılan növbətçi komanda üzvü var.","also":["növbədə","növbətçi","on call","on-call"]},{"id":"replyby","g":"run","word":"Cavab vaxtı","text":"Kartın ilk cavab üçün nə qədər gözləyə biləcəyi, məsələn insident üçün bir saat. Ondan sonra qırmızı saat alır ki, heç nə səssizcə unudulmasın. Cavab hədəfi də deyilir.","also":["cavab vaxtları","cavab hədəfi","cavab hədəfləri"]},{"id":"postmortem","g":"run","word":"İnsident təhlili","text":"İnsidentdən sonra qısa geriyə baxış: nə baş verdi, nə kömək etdi və nəyi dəyişmək lazımdır, heç kimi günahlandırmadan. İnsident onsuz bağlana bilməz.","also":["post-mortem","postmortem","insidentdən sonrakı baxış"]},{"id":"problem","g":"run","word":"Problem","text":"Bir və ya bir neçə insidentin arxasındakı gizli səbəb. 🧩 Problem kartı təkrar-təkrar qayıdan insidentləri qruplaşdırır ki, səbəb tapılsın və birdəfəlik düzəldilsin.","also":["problemlər"],"noTip":1},{"id":"rootcause","g":"run","word":"Əsas səbəb","text":"Nəyinsə xarab olmasının əsl səbəbi, sadəcə gördüyünüz nasazlıq yox. Əsas səbəbi düzəldin, insident qayıtmağı dayandırar.","also":["əsas səbəblər","kök səbəb","root cause"]},{"id":"workaround","g":"run","word":"Müvəqqəti həll","text":"Əsl düzəliş hazır olana qədər işləri yürütmək yolu, məsələn ilişib qalanda nəyisə yenidən başlatmaq. Problem kartında yazılır ki, heç kim onu yenidən axtarmalı olmasın.","also":["müvəqqəti həllər","workaround"]},{"id":"knownerror","g":"run","word":"Məlum xəta","text":"Səbəbi başa düşülən, amma hələ düzəldilməyən problem; adətən yazılmış müvəqqəti həll yolu ilə. 🧩 Məlum xətalar onları siyahılayır; beləliklə hamı yenidən araşdırmaq əvəzinə həmin yoldan istifadə edir.","also":["məlum xətalar","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Məlum növ problemi düzəltmək üçün addım-addım təlimat, hər dəfə eyni qaydada, tez edilsin deyə. Böyük insidentdən sonra komanda sizin təsdiqiniz üçün birini təklif edə bilər.","also":["runbook-lar","təlimat"]},{"id":"ci","g":"run","word":"Konfiqurasiya elementi","text":"Xidmətinizin asılı olduğu bir şey: server, domen, sertifikat, açar və ya təchizatçı kimi. 🗂️ Konfiqurasiya elementləri onları hər xidmət üzrə göstərir ki, insidentin nəyə təsir etdiyini və nəyin yenilənməli və ya ehtiyat nüsxəyə ehtiyacı olduğunu görəsiniz.","also":["konfiqurasiya elementləri"]},{"id":"expiry","g":"run","word":"Bitmə tarixi","text":"Yenilənməsə nəyinsə işləməyi dayandırdığı tarix, məsələn, saytın təhlükəsizlik sertifikatı və ya veb ünvanı. AI-gile bu tarixləri izləyir və hər biri üçün 30 gün əvvəl yenilənmə kartı yaradır ki, heç nə gözlənilmədən dayanmasın.","also":["bitmə tarixləri","bitmə","bitmə izləməsi"]},{"id":"backup","g":"run","word":"Ehtiyat nüsxə","text":"Məlumatlarınızın əvvəlki vaxtdan saxlanmış nüsxəsi, nəsə itərsə və ya zədələnərsə ona qayıtmaq üçün. AI-gile hər gün lövhələrinizin ehtiyat nüsxəsini çıxarır.","also":["ehtiyat nüsxələr","backup"]},{"id":"restore","g":"run","word":"Bərpa","text":"Məlumatları ehtiyat nüsxədən geri qaytarmaq. Ehtiyat nüsxə yalnız bərpa oluna bildiyini bildikdə həqiqətən sayılır, ona görə də arabir sınamağa dəyər.","also":["bərpa et","bərpa edildi","restore"]},{"id":"svcreview","g":"run","word":"Xidmət baxışı","text":"Xidmətin bir ayına geriyə baxış: açılan və həll olunan insidentlər, insanların nə qədər tez cavab aldığı, işləmə vaxtı və istifadə olunan tokenlər. Aylıq baxış bunu hər xidmət üçün göstərir.","also":["xidmət baxışları","aylıq baxış","aylıq baxışlar"]},{"id":"accessreview","g":"run","word":"Giriş baxışı","text":"Hər 90 gündə kimin hələ də içəri girə bildiyini yoxlamaq: paylaşma linkləri, dostların rolları, saxlanmış parollar və açarlar. Hər birini saxlayırsan və ya çıxarırsan ki, köhnə girişlər qalmasın.","also":["giriş baxışları"]},{"id":"improvements","g":"run","word":"Təkmilləşdirmə siyahısı","text":"Komandanın yaxşılaşdırmağa qərar verdiyi hər şey bir yerdə: retro təklifləri, baxış tədbirləri və problem düzəlişləri, hər biri öz statusu ilə. Onu 📈 Təkmilləşdirmələr bölməsində tapın.","also":["təkmilləşdirmə siyahıları","təkmilləşdirmələr"]},{"id":"tokencap","g":"run","word":"Token limiti","text":"Xidmətin agentlərinin istifadə edə biləcəyi tokenlərə aylıq limit. 80%-də xəbərdarlıq alırsınız; 100%-də onların arxa fon işi növbəti aya və ya siz limiti artırana qədər gözləyir.","also":["token limitləri"]},{"id":"svcmgmt","g":"run","word":"Xidmət idarəetməsi","text":"Xidməti ona arxalanan insanlar üçün gündən-günə faydalı və işlək saxlamağa aid hər şey.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Yaxşı xidmət idarəetməsi üçün geniş istifadə olunan bələdçi; insidentlər, problemlər və dəyişikliklər kimi məsələləri əhatə edir. Ad vaxtilə IT Infrastructure Library demək idi."},{"id":"itsm","g":"run","word":"İT xidmətlərinin idarə edilməsi (ITSM)","text":"Texnologiyanı insanlar üçün xidmət kimi idarə etmək; sorğuları, insidentləri, dəyişiklikləri və təkmilləşdirmələri həll etməyin aydın yolları ilə.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"İdarə olunan xidmət","text":"Başqasının sənin üçün işlətdiyi və baxdığı xidmət; nə qədər yaxşı işləməli olduğu barədə razılaşma əsasında.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"Xidmət sahibi","text":"Xidmətə bütövlükdə cavabdeh olan adam: nə qədər yaxşı işləməsi, nəyə başa gəlməsi və necə yaxşılaşması.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"Xidmət səviyyəsi razılaşması (SLA)","text":"Xidmətin nə qədər yaxşı işləyəcəyinə dair müştərilərə yazılı vəd, məsələn, «vaxtın 99,9%-ində işləkdir» və ya «bir saat ərzində cavab verilir»; pozulsa, çox vaxt pul geri qaytarılır.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Xidmət səviyyəsi hədəfi (SLO)","text":"Xidmətin bir dövrdə nə qədər yaxşı işləməli olduğuna dair komandanın öz hədəfi; təhlükəsiz olmaq üçün adətən SLA-dan bir az ciddi qoyulur.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Xidmət səviyyəsi göstəricisi (SLI)","text":"Hədəflə müqayisə etdiyin real ölçmə, məsələn, normal yüklənən ziyarətlərin payı.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Əlçatımlılıq (availability)","text":"İnsanların ehtiyac duyanda xidmətdən istifadə edə bilib-bilməməsi; çox vaxt uptime kimi ölçülür.","also":["availability","high availability","yüksək əlçatımlılıq"]},{"id":"downtime","g":"run","word":"Dayanma vaxtı (downtime)","text":"Xidmətin işləmədiyi və ya söndürüldüyü vaxt, planlı və ya planlı olmayaraq.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Xəta büdcəsi","text":"Etibarlılıq hədəfinin icazə verdiyi kiçik uğursuzluq miqdarı. Qalan olduqca dəyişikliklərdə risk götürə bilərsən; bitəndə yavaşlayırsan.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Kəsinti (outage)","text":"Xidmətin istifadəçilər üçün dayandığı və ya ciddi sındığı vaxt.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Zəifləmiş (degraded)","text":"İşləyir, amma pis: yavaş və ya bəzi hissələri işləmir.","also":["degraded","degraded service","zəifləmiş xidmət"]},{"id":"monitoring","g":"run","word":"Monitorinq","text":"Xidməti daim avtomatik izləmək ki, problemlər, ideal halda istifadəçilər hiss etməmişdən əvvəl, aşkar edilsin.","also":["monitoring"]},{"id":"observability","g":"run","word":"Müşahidəolunanlıq (observability)","text":"Sistemin içində nələr baş verdiyini onun jurnallarına, rəqəmlərinə və izlərinə baxaraq kənardan nə qədər yaxşı anlaya bilməyin.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Jurnal (log)","text":"Proqramın nə etdiyinə dair apardığı gündəlik; nəyin səhv getdiyini anlamaq üçün istifadə olunur.","also":["log","logs","logging","jurnallar"],"noTip":1},{"id":"trace","g":"run","word":"İz (trace)","text":"Bir sorğunun sistemin müxtəlif hissələrindən addım-addım necə keçdiyinin qeydi; harada ləngidiyini göstərir.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Gecikmə (latency)","text":"Bir şeyin cavab verməsinin nə qədər çəkməsi, məsələn, klikləməklə səhifənin görünməsi arasındakı gözləmə.","also":["latency","gecikmə müddəti"]},{"id":"alert","g":"run","word":"Xəbərdarlıq (alert)","text":"Nəyəsə diqqət lazım olduğunu bildirən avtomatik mesaj, məsələn, saytın cavab verməməsi.","also":["alert","alerts","alerting","xəbərdarlıqlar"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Xəbərdarlıq yorğunluğu","text":"O qədər çox xəbərdarlıq olur ki, insanlar onlara, vacib olanlara da, məhəl qoymamağa başlayır.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"İdarə paneli (dashboard)","text":"Ən vacib rəqəmləri və vəziyyətləri bir baxışda göstərən ekran.","also":["dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Çağırış (paging)","text":"Problem barədə növbətçi adamı təcili çağırmaq və ya oyatmaq.","also":["paging","paged","paging alert"]},{"id":"escalation","g":"run","word":"Eskalasiya","text":"Məsələ cari səviyyədə həll olunmayanda və ya kifayət qədər tez həll olunmayanda daha bacarıqlı və ya səlahiyyətli adamı işə cəlb etmək.","also":["escalation","escalate","escalated","yüksək səviyyəyə ötürmə"]},{"id":"triage","g":"run","word":"Triaj (triage)","text":"Gələn məsələləri təcililiyinə və vacibliyinə görə tez çeşidləmək; ən pisinə əvvəl baxılsın deyə.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Təsir (impact)","text":"Bir şeyin insanlara nə qədər təsir etməsi: neçə nəfərə və nə qədər ciddi.","noTip":1},{"id":"urgency","g":"run","word":"Təcililik (urgency)","text":"Bir şeyə nə qədər tez baxılmalı olduğu. Təsir və təcililik birlikdə prioriteti müəyyən edir.","noTip":1},{"id":"plevels","g":"run","word":"Prioritet səviyyələri (P1, P2…)","text":"Məsələnin nə qədər təcili olduğunu göstərən etiketlər. P1 ən ciddisidir və dərhal tədbir tələb edir.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Tiket növbəsi","text":"Götürülməyi gözləyən sorğuların və insidentlərin siyahısı.","also":["ticket queue","ticket queues","tiket növbələri"]},{"id":"tiers","g":"run","word":"Birinci və ikinci xətt","text":"Dəstək səviyyələri: birinci xətt zəngi qəbul edir və sadə şeyləri düzəldir; ikinci xəttin çətinləri üçün daha dərin bacarıqları var. Tier 1 və tier 2 də deyilir.","also":["first-line support","tier 1","tier 2","birinci xətt","ikinci xətt"]},{"id":"ic","g":"run","word":"İnsident komandiri","text":"İnsidentə cavab tədbirlərinə rəhbərlik edən tək adam; hamı kimin qərar verdiyini və kimin nə etdiyini bilsin deyə.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Cavab müddəti","text":"Kiminsə sorğunu və ya insidenti ilk dəfə götürməsinə qədər keçən vaxt.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Həll müddəti","text":"Sorğunun və ya insidentin bildirilməsindən tam həll olunmasına qədər keçən vaxt.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Orta bərpa vaxtı (MTTR)","text":"Xidmət sındıqdan sonra onu yenidən işlək hala gətirməyin orta hesabla nə qədər çəkməsi. MTTR bir qədər fərqli mənalar verə bilər, ona görə nəyi ölçdüyünü de.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Nasazlıqlar arası orta vaxt (MTBF)","text":"Xidmətin nəsə sınana qədər orta hesabla nə qədər işləməsi.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Konfiqurasiya idarəetmə bazası (CMDB)","text":"Bütün konfiqurasiya elementlərinin və onların necə bağlı olduğunun siyahısı; nəyin nədən asılı olduğunu görəsən deyə.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Aktiv (asset)","text":"Xidməti işlətmək üçün sahib olduğun və ya ödədiyin dəyərli hər şey, məsələn, noutbuk, proqram lisenziyası və ya domen.","also":["asset","assets","aktivlər"],"noTip":1},{"id":"capplan","g":"run","word":"Tutum planlaşdırması","text":"Gələn şeylər üçün kifayət qədər kompüter gücünün, yaddaşın və adamın olacağına əmin olmaq.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Miqyaslama","text":"Daha çox istifadəçiyə tab gətirmək: ya maşına daha çox güc vermək (yuxarı miqyaslama), ya da daha çox maşın əlavə etmək (üfüqi miqyaslama).","also":["scaling","scale up","scale out","scaling up","scaling out","miqyaslandırma"]},{"id":"bcp","g":"run","word":"İş davamlılığı","text":"Böyük bir şey səhv gedəndə, məsələn, ofis, əsas təchizatçı və ya kompüterlər itəndə, vacib işləri davam etdirmək planları.","also":["business continuity","business continuity plan","iş davamlılığı planı"]},{"id":"dr","g":"run","word":"Fəlakətdən bərpa (DR)","text":"Ciddi bir hadisədən, məsələn, bütöv data mərkəzinin itməsindən sonra xidməti bərpa etmək planı və alətləri.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Bərpa vaxtı hədəfi (RTO)","text":"Xidmətin fəlakətdən sonra yenidən işləməzdən əvvəl ən çox nə qədər dayana biləcəyi vaxt.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Bərpa nöqtəsi hədəfi (RPO)","text":"Son məlumatdan nə qədərini itirməyə dözə biləcəyin, vaxtla ölçülür. Bir saatlıq RPO ən azı saatda bir ehtiyat nüsxə deməkdir.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Rezervləmə (redundancy)","text":"İkinci server kimi hazır ehtiyatlara malik olmaq; beləliklə bir nasazlıq xidməti dayandırmasın.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover (ehtiyata keçid)","text":"Adi sistem sıradan çıxanda özbaşına ehtiyat sistemə keçmək.","also":["failover","fail over","ehtiyata keçid"]},{"id":"spof","g":"run","word":"Tək nasazlıq nöqtəsi","text":"Ehtiyatı olmadığı üçün sınanda hər şeyi özü ilə yıxan tək hissə.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Texniki xidmət pəncərəsi","text":"Xidmətin təmir üçün dayandırıla və ya yavaşlaya biləcəyi, istifadəçilərə əvvəlcədən elan edilən planlı vaxt.","also":["maintenance window","maintenance windows","planned maintenance","planlı texniki işlər"]},{"id":"handover","g":"run","word":"Təhvil-təslim (handover)","text":"İşi, bilikləri və məsuliyyəti başqa adama və ya komandaya ötürmək; heç nə itməsin deyə.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Biliklər bazası","text":"İstifadəçilər və komanda üçün kömək məqalələri və cavablar toplusu.","also":["knowledge base","knowledge bases","bilik bazası"]},{"id":"csat","g":"run","word":"Müştəri məmnuniyyəti (CSAT)","text":"İstifadəçilərin nə qədər razı qaldığını deyən bal; çox vaxt sorğu bağlandıqdan sonra soruşulur.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Təchizatçı","text":"Arxalandığın kənar şirkət, məsələn, hostinq provayderin. Vendor və ya üçüncü tərəf də deyilir.","also":["supplier","suppliers","vendor","vendors","third party","üçüncü tərəf"],"noTip":1},{"id":"retire","g":"run","word":"Xidmətin bağlanması","text":"Xidməti birdəfəlik və təhlükəsiz söndürmək: istifadəçilərə xəbər vermək, məlumatı və giriş hüquqlarını qaydasına salmaq və xərclərini dayandırmaq.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Ömrünün sonu (EOL)","text":"Məhsulun istehsalçısından yeniləmə və ya dəstək almağı dayandırdığı vaxt; ona görə dəyişdirilməlidir.","also":["EOL","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Kibertəhlükəsizlik","text":"Sistemləri və məlumatı sındırılmaqdan, oğurlanmaqdan və ya zədələnməkdən qorumaq.","also":["cybersecurity","cyber security","kiber təhlükəsizlik"]},{"id":"authn","g":"sec","word":"Autentifikasiya","text":"Kiminsə kim olduğunu yoxlamaq, adətən parol və ya kodla. Çox vaxt authn kimi qısaldılır.","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"Avtorizasiya","text":"Kimin olduğunu biləndən sonra ona nəyə icazə verildiyini yoxlamaq. Çox vaxt authz kimi qısaldılır.","also":["authorisation","authorization","authz"]},{"id":"mfa","g":"sec","word":"Çoxfaktorlu autentifikasiya (MFA)","text":"İki və ya daha çox sübutla daxil olmaq, məsələn, parol və telefondakı kod. İki faktorlu (2FA) da deyilir.","also":["MFA","2FA","two-factor","two-factor authentication","iki faktorlu","iki mərhələli doğrulama"]},{"id":"sso","g":"sec","word":"Vahid giriş (SSO)","text":"Bir dəfə daxil olub çoxlu sistemə girmək, məsələn, iş hesabından hər yerdə istifadə etmək.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Parol meneceri","text":"Güclü parollar yaradan və onları sənin üçün yadda saxlayan tətbiq.","also":["password manager","password managers","parol menecerləri"]},{"id":"secret","g":"sec","word":"Gizli məlumat (secret)","text":"Proqramın nəyəsə girmək üçün işlətdiyi parol, açar və ya başqa gizli kod. Heç vaxt paylaşılmamalı və ya koda yazılmamalıdır.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API açarı","text":"Proqrama başqa xidmətin API-sindən istifadə etməyə imkan verən gizli kod; kimin onu istifadə etdiyini (və ödədiyini) göstərir.","also":["API key","API keys","API açarları"]},{"id":"accesstoken","g":"sec","word":"Giriş tokeni (access token)","text":"Proqramın içəri girməyə icazəsi olduğunu sübut edən müvəqqəti giriş vərəqəsi; beləliklə ona hər dəfə parolun lazım olmur. AI tokeni ilə eyni deyil.","also":["access token","access tokens","giriş tokenləri"]},{"id":"encryption","g":"sec","word":"Şifrələmə","text":"Məlumatı qarışdırmaq ki, yalnız düzgün açarı olan oxuya bilsin.","also":["encryption","encrypted","encrypt","şifrələnmiş"]},{"id":"https","g":"sec","word":"HTTPS","text":"Veb səhifələrin təhlükəsiz yolu; brauzerindəki asma qifil bunu göstərir. Aradakı heç kim onları oxuya və ya dəyişə bilmir."},{"id":"cert","g":"sec","word":"SSL/TLS sertifikatı","text":"Saytın kim olduğunu sübut etməyə və HTTPS-dən istifadə etməyə imkan verən rəqəmsal şəxsiyyət vəsiqəsi. Müddəti bitir, ona görə yenilənməlidir.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikat","sertifikatlar"]},{"id":"permissions","g":"sec","word":"İcazələr","text":"Kimin nəyi görə və ya dəyişə biləcəyinə dair qaydalar.","also":["permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minimum imtiyaz","text":"Hər adama və ya proqrama yalnız həqiqətən ehtiyac duyduğu girişi, yalnız ehtiyac duyduğu müddətə vermək.","also":["least privilege","principle of least privilege","ən az imtiyaz prinsipi"]},{"id":"rbac","g":"sec","word":"Rol əsaslı giriş nəzarəti (RBAC)","text":"Girişi adambaadam yox, rola görə vermək, məsələn, izləyici və ya redaktor.","also":["RBAC","role-based access control","role-based access"]},{"id":"vuln","g":"sec","word":"Zəiflik (vulnerability)","text":"Kiminsə içəri girmək və ya ziyan vurmaq üçün istifadə edə biləcəyi zəif nöqtə.","also":["vulnerability","vulnerabilities","zəifliklər"]},{"id":"zeroday","g":"sec","word":"Zero-day (sıfırıncı gün)","text":"Hücumçuların bildiyi, amma istehsalçıların düzəltməyə hələ fürsət tapmadığı zəiflik.","also":["zero-day","zero-days","zero day","sıfırıncı gün"]},{"id":"malware","g":"sec","word":"Zərərli proqram (malware)","text":"Zərər vurmaq, casusluq etmək və ya oğurlamaq üçün hazırlanmış zərərli proqram, məsələn, viruslar.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Fidyə proqramı (ransomware)","text":"Fayllarını kilidləyən və açmaq üçün pul tələb edən zərərli proqram. Ən yaxşı müdafiə yaxşı ehtiyat nüsxələrdir.","also":["ransomware","ransomware attack","fidyə hücumu"]},{"id":"phishing","g":"sec","word":"Fişinq (phishing)","text":"Səni parolunu və ya pulunu verməyə, ya da zərərli bir şey açmağa aldatmağa çalışan saxta mesajlar.","also":["phishing","phishing email","phishing emails","fişinq məktubu"]},{"id":"socialeng","g":"sec","word":"Sosial mühəndislik","text":"Kompüterləri yox, insanları girişi verməyə aldatmaq, məsələn, «IT dəstəyi»ndən saxta zəng."},{"id":"firewall","g":"sec","word":"Firewall (şəbəkə qalxanı)","text":"Hansı şəbəkə trafikinin içəri girə və ya çıxa biləcəyini müəyyən edən keşikçi.","also":["firewall","firewalls","brandmauer"]},{"id":"vpn","g":"sec","word":"VPN","text":"Virtual private network-ün qısası: internet üzərindən qarışdırılmış şəxsi bağlantı; çox vaxt iş sistemlərinə təhlükəsiz çatmaq üçün istifadə olunur.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Xidmətdən imtina hücumu (DoS, DDoS)","text":"Xidməti o qədər saxta trafiklə doldurmaq ki, real insanlar istifadə edə bilməsin. DDoS bunun eyni anda çoxlu kompüterdən gəldiyini göstərir.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Nüfuz testi (pen test)","text":"İçəri girməyə cəhd etmək üçün xoşniyyətli ekspertləri işə götürmək; beləliklə zəifliklər real hücumçulardan əvvəl tapılır.","also":["pen test","pen testing","penetration testing","pentest","penetration test"]},{"id":"audit","g":"sec","word":"Təhlükəsizlik auditi","text":"Nəyinsə nə qədər yaxşı qorunduğunun yaxşı təcrübələr siyahısı əsasında diqqətli yoxlanması.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Təhdid modelləşdirməsi","text":"Kimin nəyə hücum edə biləcəyini, necə edəcəyini və onu dayandırmaq üçün sənin nə edəcəyini düşünüb-daşınmaq.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Məlumat sızması","text":"Şəxsi məlumatın ona sahib olmamalı adamlara çıxması, itməsi və ya icazəsiz dəyişdirilməsi.","also":["data breach","data breaches","məlumat pozuntusu"]},{"id":"pii","g":"sec","word":"Şəxsi məlumat","text":"Kimliyi müəyyən edilə bilən adama aid hər məlumat, məsələn, ad, e-poçt ünvanı və ya yer. PII də deyilir.","also":["PII","personally identifiable information","personal data"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Şəxsi məlumata dair Avropa qanunu (Böyük Britaniyanın öz variantı var): yalnız lazım olanı topla, təhlükəsiz saxla və insanlara öz məlumatını görməyə və ya silməyə icazə ver.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Məlumatların qorunması","text":"Şəxsi məlumata düzgün və qanun çərçivəsində qulluq etmək.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Məxfilik siyasəti","text":"Hansı şəxsi məlumatı nə üçün topladığını və onunla nə etdiyini deyən açıq səhifə.","also":["privacy policy","privacy statement","privacy notice","məxfilik bəyanatı"]},{"id":"consent","g":"sec","word":"Razılıq (consent)","text":"Adamın məlumatının müəyyən qaydada istifadə olunmasına açıq, sərbəst «bəli»si. O, istənilən vaxt geri götürə bilər.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Kuki (cookie)","text":"Saytın nəyisə, məsələn, daxil olduğunu, yadda saxlamaq üçün brauzerində saxladığı kiçik fayl. Bəzilərinə əvvəl razılığın lazımdır.","also":["cookie","cookies","kukilər"],"noTip":1},{"id":"minimisation","g":"sec","word":"Məlumatın minimallaşdırılması","text":"İş üçün həqiqətən lazım olan şəxsi məlumatı toplamaq və saxlamaq, artığını yox.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Məlumatın saxlanma müddəti","text":"Məlumatın silinməzdən əvvəl nə qədər saxlandığı. Lazım olandan çox saxlamamaq daha təhlükəsizdir və çox vaxt qanundur.","also":["data retention","retention period","saxlama müddəti"]},{"id":"anon","g":"sec","word":"Anonimləşdirmə","text":"Məlumatı elə dəyişmək ki, ondan artıq heç kimi əsaslı şəkildə tanımaq mümkün olmasın.","also":["anonymisation","anonymised","anonymization","anonymous data","anonim məlumat"]},{"id":"pseudo","g":"sec","word":"Psevdonimləşdirmə","text":"Adları və digər təfərrüatları kodlarla əvəz etmək; onları geri bağlamaq üçün açar ayrıca saxlanılır. Bu, hələ də şəxsi məlumatdır.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Məlumat emalı razılaşması (DPA)","text":"Təchizatçının sənin adından şəxsi məlumatı necə emal edə biləcəyini deyən müqavilə.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Məlumatların qorunmasına təsirin qiymətləndirilməsi (DPIA)","text":"Başlamazdan əvvəl şəxsi məlumatdan istifadə planının insanlara necə təsir edə biləcəyinə və riskləri necə azaltmağa diqqətli baxış.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Audit jurnalı","text":"Kimin nəyi nə vaxt etdiyinin qeydi; hərəkətlər sonra yoxlanıla bilsin deyə.","also":["audit log","audit logs","audit trail","audit izi"]},{"id":"compliance","g":"sec","word":"Uyğunluq (compliance)","text":"Sənə aid qanunlara, qaydalara və standartlara əməl etmək və buna əməl etdiyini göstərə bilmək.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"İnformasiya təhlükəsizliyini idarə etmək üçün tanınmış beynəlxalq standart. Şirkətlər bu standarta uyğunluq sertifikatı ala bilər.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Xarici auditorlar tərəfindən yoxlanılan ABŞ hesabatı; şirkətin müştəri məlumatına düzgün baxdığını göstərir.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Tapşırıq üzərində özbaşına işləyən AI: kodu oxuyur, dəyişikliklər edir, yoxlamalar aparır və hesabat verir. İşi hələ də yoxlanılır.","also":["agentlər"]},{"id":"token","g":"ai","word":"Token","text":"AI-nin oxuduğu və yazdığı kiçik mətn parçaları, hər biri təxminən sözün dörddə üçü qədər. AI istifadəsi tokenlərlə sayılır, ona görə nə qədər az token işlənsə, planından bir o qədər çox qalır.","also":["tokenlər"]},{"id":"hook","g":"ai","word":"Hook","text":"Müəyyən anda, məsələn, AI sessiyası başlayanda, özbaşına işləyən kiçik əmr; beləliklə komanda şərhlərini eşidir.","also":["hook-lar"]},{"id":"ai","g":"ai","word":"Süni intellekt (AI)","text":"Adətən insan tələb edən işlər görən kompüter sistemləri, məsələn, yazmaq, suallara cavab vermək və ya şəkilləri tanımaq.","also":["AI","artificial intelligence","süni intellekt"],"noTip":1},{"id":"ml","g":"ai","word":"Maşın öyrənməsi (ML)","text":"Kompüterlərə dəqiq qaydalar vermək əvəzinə, çoxlu nümunədən qanunauyğunluqları öyrətmək üsulu.","also":["ML","machine learning","maşın öyrənməsi"]},{"id":"model","g":"ai","word":"Model","text":"AI sisteminin təlim keçmiş «beyni»; çoxlu nümunədən öyrənərək qurulub. Modellər bacarığına, sürətinə və qiymətinə görə fərqlənir.","also":["models","AI model","modellər","AI modeli"],"noTip":1},{"id":"llm","g":"ai","word":"Böyük dil modeli (LLM)","text":"Böyük miqdarda mətn üzərində təlim keçmiş AI modeli; dili oxuya və yaza bilir.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"Generativ AI","text":"Yalnız çeşidləmək və ya tanımaq əvəzinə, mətn, şəkil və ya kod kimi yeni şeylər yaradan AI.","also":["GenAI","generative AI","generativ süni intellekt"]},{"id":"chatbot","g":"ai","word":"Çatbot","text":"Yazaraq və ya danışaraq gündəlik dildə söhbət etdiyin proqram.","also":["chatbot","chatbots","çat-bot"]},{"id":"prompt","g":"ai","word":"Prompt (AI-yə sorğu)","text":"AI-yə verdiyin şey: sualın və ya təlimatların və ona verdiyin hər şey. Aydın prompt-lar adətən daha yaxşı cavab alır.","also":["prompt","prompts","sorğu mətni"]},{"id":"prompteng","g":"ai","word":"Prompt mühəndisliyi","text":"Etibarlı, faydalı nəticə verən prompt-lar yazmaq bacarığı.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Sistem promptu","text":"AI-yə söhbət başlamazdan əvvəl verilən, onun rolunu və qaydalarını müəyyən edən fon təlimatlar. Sənin yazdığından daha çox çəkisi var.","also":["system prompt","system prompts","system instruction","system instructions","sistem təlimatı"]},{"id":"context","g":"ai","word":"Kontekst","text":"AI-nin işləyərkən görə bildiyi hər şey: təlimatlar, mesajların, oxuduğu fayllar və əvvəlki cavablar.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekst pəncərəsi","text":"AI-nin eyni anda nə qədərini yadda saxlaya bildiyi, tokenlərlə ölçülür. Bundan sonra köhnə hissələr atılır və ya xülasə olunur.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Sessiya","text":"AI ilə başdan sona bir iş söhbəti. Yeni sessiya təzə yaddaşla başlayır.","also":["session","sessions","sessiyalar"],"noTip":1},{"id":"memory","g":"ai","word":"Yaddaş","text":"AI-nin sessiyalar arasında saxladığı qeydlər; seçimlərini və əvvəlki qərarları xatırlasın deyə.","noTip":1},{"id":"hallucination","g":"ai","word":"Halüsinasiya","text":"AI-nin əmin səslənən, amma uydurma və ya yanlış bir şey deməsi. Vacib faktları yoxla.","also":["hallucination","hallucinations","hallucinate","hallucinates","halüsinasiyalar"]},{"id":"training","g":"ai","word":"Təlim (training)","text":"Modeli, onu kimsə istifadə etməzdən əvvəl, çoxlu nümunə göstərərək öyrətmək.","also":["training","trained","təlim","öyrədilmə"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Təlim məlumatı","text":"Modelin öyrəndiyi nümunələr. Onun biliyi bu məlumatın toplandığı tarixdə dayanır.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Bilik həddi (knowledge cutoff)","text":"AI-nin daxili biliyinin bitdiyi tarix. Axtarıb tapmasa, sonrakı şeyləri bilməyəcək.","also":["knowledge cutoff","training cutoff","təlim həddi"]},{"id":"finetune","g":"ai","word":"İncə tənzimləmə (fine-tuning)","text":"Mövcud modelin öz nümunələrin üzərində əlavə təlimi; onu bir konkret işdə daha yaxşı etmək üçün.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"İnferens (inference)","text":"AI modelinin təlim keçmək əvəzinə, nəyəsə cavab vermək üçün həqiqətən istifadə olunması.","also":["inference","model inference","nəticə çıxarma"]},{"id":"tooluse","g":"ai","word":"Alət istifadəsi","text":"AI-nin yalnız danışmayıb, tətbiqin verdiyi alətlərlə nəsə edə bilməsi: əmr işlətmək, fayl oxumaq və ya vebdə axtarmaq.","also":["tool use","tool calling","tool call","tool calls","alət çağırışı"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Əsas AI-nin daha kiçik işi verdiyi və nəticəni geri aldığı köməkçi AI.","also":["subagent","subagents","sub-agent","alt agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent (çoxagentli)","text":"Bir iş üzərində birlikdə işləyən bir neçə AI; hər birinin öz hissəsi var, kiçik komanda kimi.","also":["multi-agent","multi-agent system","çoxagentli sistem"]},{"id":"autonomy","g":"ai","word":"Muxtariyyət (autonomy)","text":"AI-nin insandan soruşmazdan əvvəl özbaşına nə qədər iş görə bilməsi.","also":["autonomy","autonomous","muxtar"]},{"id":"hitl","g":"ai","word":"Prosesdə insan (human in the loop)","text":"AI-nin gördüklərini əsas məqamlarda yoxlamaq və ya təsdiqləmək üçün insanı prosesdə saxlamaq. AI-gile-də bu sənsən.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Qoruyucu çərçivələr (guardrails)","text":"AI-nin hərəkətlərini təhlükəsiz saxlayan limitlər və yoxlamalar, məsələn, nəyisə canlıya çıxarmazdan əvvəl təsdiq tələb etmək. Səhv riskini azaldır, amma tamamilə aradan qaldırmır.","also":["guardrails","guardrail","qoruyucu məhdudiyyətlər"]},{"id":"rag","g":"ai","word":"Axtarışla gücləndirilmiş generasiya (RAG)","text":"AI-yə cavab verməzdən əvvəl öz sənədlərinə baxmağa imkan vermək; beləliklə cavabları sənin faktlarına əsaslanır.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (vektor təsviri)","text":"Mətni mənasını əks etdirən ədədlər siyahısına çevirmək; kompüter oxşar mənalı şeyləri tapa bilsin deyə.","also":["embedding","embeddings","embeddinqlər"]},{"id":"vectordb","g":"ai","word":"Vektor bazası","text":"Həmin ədəd siyahılarında (embedding-lərdə) axtarmaq üçün qurulmuş baza; oxşar mənalı materialı tapır.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Alətləri və məlumat mənbələrini AI tətbiqlərinə qoşmağın ortaq yolu; AI onlardan istifadə edə bilsin deyə.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatur (temperature)","text":"AI cavablarının nə qədər cəsarətli olduğunu müəyyən edən parametr. Aşağı olsa cavablar sabit və proqnozlaşdırıla bilən, yüksək olsa daha müxtəlif olur. Heç biri onun həmişə düz olmasını təmin etmir.","also":["temperature","model temperature","model temperaturu"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Birdən çox növ məlumatla, məsələn, mətn, şəkil və səslə işləyə bilən.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Qiymətləndirmə (eval)","text":"AI-nin seçilmiş nümunələrdə nə qədər yaxşı işlədiyinin planlı testi; modelləri və ya promptları müqayisə edə biləsən deyə.","also":["eval","evals","evaluation","qiymətləndirmələr"]},{"id":"bias","g":"ai","word":"Qərəz (bias)","text":"AI-nin (və ya insanın) haqsız olaraq bir tərəfə meyl etməsi; çox vaxt öyrəndiyi şeylərə görə.","also":["bias","biased","qərəzlilik"],"noTip":1},{"id":"responsible","g":"ai","word":"Məsuliyyətli AI","text":"AI-dən ədalətli, təhlükəsiz və dürüst istifadə etmək; nəticələrə görə hələ də insanlar cavabdehdir.","also":["responsible AI","ethical AI","etik AI"]},{"id":"injection","g":"ai","word":"Prompt injection (prompt yeridilməsi)","text":"Veb səhifədə və ya faylda gizli təlimatların AI-ni istifadəçisinin istəmədiyi bir şeyi etməyə məcbur etməyə çalışdığı hiylə.","also":["prompt injection","prompt injections","prompt yeridilməsi"]},{"id":"ratelimit","g":"ai","word":"Sorğu limiti (rate limit)","text":"Xidmətə müəyyən vaxtda göndərə biləcəyin sorğuların sayına qoyulan hədd. Aşsan, gözləməlisən.","also":["rate limit","rate limits","rate limited","sürət limiti"]},{"id":"usagelimit","g":"ai","word":"İstifadə limiti","text":"Planının bir dövrdə icazə verdiyi AI işinin miqdarı; ondan sonra dayanır və ya daha baha olur.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Proqramı əsasən nə istədiyini AI-yə təsvir edib kodu onun yazmasına icazə verməklə qurmaq.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Büdcə","text":"Nəyinsə üçün ayrılmış pul məbləği.","also":["budget","budgets","büdcələr"],"noTip":1},{"id":"costest","g":"money","word":"Xərc təxmini","text":"Başlamazdan əvvəl nəyinsə nəyə başa gələcəyinə dair ən yaxşı təxmin.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"İnvestisiyanın gəlirliliyi (ROI)","text":"Qoyduğunla müqayisədə nə qazandığın. Müsbətdirsə, buna dəyib.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Ümumi sahiblik dəyəri (TCO)","text":"Nəyinsə bütün ömrü boyu həqiqətən nəyə başa gəldiyi, yalnız alış qiyməti yox: işlətmə, dəstək, təkmilləşdirmə və nəhayət, istifadədən çıxarmaq.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx və OpEx","text":"CapEx saxladığın şeylərə əvvəldən xərclənən puldur; OpEx isə aylıq hesablar kimi davamlı xərcdir.","also":["CapEx","OpEx","capital expenditure","operating expenditure","kapital xərcləri","əməliyyat xərcləri"]},{"id":"subscription","g":"money","word":"Abunə","text":"Nədənsə istifadəni davam etdirmək üçün müntəzəm, adətən aylıq və ya illik ödəmək.","also":["subscription","subscriptions","abunəlik"],"noTip":1},{"id":"saas","g":"money","word":"Xidmət kimi proqram (SaaS)","text":"Onlayn istifadə etdiyin və abunə ilə ödədiyin proqram; onu sənin üçün yaradıcısı işlədir.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"İstifadə qədər ödəmə","text":"Yalnız istifadə etdiyin qədər ödəmək, məsələn, bulud hesablama və ya AI tokenləri üçün.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Limit aşımı (overage)","text":"Planının daxil etdiyindən artıq istifadə; əlavə pula başa gələ bilər.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Ödəniş xəbərdarlığı","text":"Xərc və ya istifadə seçdiyin həddə çatanda gələn mesaj. Səni xəbərdar edir, amma həmişə əlavə ödənişləri dayandırmır.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Pulsuz səviyyə (free tier)","text":"Ödənişli xidmətin məhdudiyyətləri olan pulsuz səviyyəsi. Başlayarkən əlverişlidir.","also":["free tier","free plan","pulsuz plan"]},{"id":"pricing","g":"money","word":"Qiymət planı","text":"Xidmətin satdığı müxtəlif paketlər; hər birinin öz qiyməti və limitləri var.","also":["pricing plan","pricing plans","price plan","tarif planı"]},{"id":"licence","g":"money","word":"Lisenziya","text":"Başqasının hazırladığı şeyi, məsələn, proqramı, şriftləri və ya şəkilləri, necə istifadə edə, kopyalaya, dəyişə və ya paylaşa biləcəyinə dair qaydalar.","also":["licence","licences","license","licenses","lisenziyalar"],"noTip":1},{"id":"opensource","g":"money","word":"Açıq mənbə (open source)","text":"Kodunu hər kəsin oxuya, istifadə edə və çox vaxt pulsuz dəyişə biləcəyi proqram; lisenziyasının qaydalarına uyğun olaraq.","also":["open source","open-source","open source software","OSS","açıq mənbə"]},{"id":"osslicence","g":"money","word":"Açıq mənbə lisenziyası","text":"Açıq mənbə koda əlavə olan qaydalar. Bəziləri demək olar ki, hər şeyə icazə verir (MIT kimi); bəziləri dəyişikliklərini də paylaşmağı istəyir (GPL kimi).","also":["open source licence","open source licences","MIT licence","GPL","MIT lisenziyası"]},{"id":"proprietary","g":"money","word":"Qapalı mənbə (proprietary)","text":"Şirkətə məxsus olan və sərbəst kopyalana və ya dəyişdirilə bilməyən. Açıq mənbənin əksi.","also":["proprietary","proprietary software","qapalı proqram"]},{"id":"copyright","g":"money","word":"Müəllif hüququ","text":"Yaradıcının öz işinin, o cümlədən kodun və yazının, nüsxələrinə nəzarət etmək qanuni hüququ.","also":["copyright","copyrighted","müəllif hüquqları"],"noTip":1},{"id":"ip","g":"money","word":"Əqli mülkiyyət (IP)","text":"Qanunun kiməsə məxsus saydığı ideyalar və yaradıcılıqlar, məsələn, kod, dizaynlar, adlar və loqolar.","also":["IP","intellectual property","əqli mülkiyyət"]},{"id":"tos","g":"money","word":"İstifadə şərtləri","text":"Xidmətdən istifadə edəndə razılaşdığın qaydalar.","also":["terms of service","terms and conditions","terms of use","xidmət şərtləri"]},{"id":"contract","g":"money","word":"Müqavilə","text":"Qanunun arxasında durduğu iki tərəf arasında yazılı razılaşma.","also":["contract","contracts","müqavilələr"],"noTip":1},{"id":"sow","g":"money","word":"İş bəyanatı (SOW)","text":"Dəqiq hansı işin, nə vaxta qədər və nə qədərə görüləcəyini göstərən sənəd.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Sabit qiymət","text":"İşin hamısı üçün razılaşdırılmış qiymət, nə qədər çəkməsindən asılı olmayaraq.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Vaxt və material (T&M)","text":"Sabit qiymət əvəzinə həqiqətən işlənmiş saatlara və həqiqətən işlədilmiş şeylərə görə ödəmək.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Faktura (invoice)","text":"Görülmüş iş və ya təchiz edilmiş mal üçün ödəniş istəyən hesab.","also":["invoice","invoices","hesab-faktura","fakturalar"],"noTip":1},{"id":"lockin","g":"money","word":"Təchizatçıya bağlılıq (vendor lock-in)","text":"Təchizatçıdan ayrılmağın o qədər çətin və ya baha olması ki, ona bağlı qalırsan.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Satınalma","text":"Təchizatçılardan seçmək və almaq prosesi.","also":["procurement","satınalmalar"]},{"id":"servicecredit","g":"money","word":"Xidmət krediti","text":"Təchizatçı SLA-sını pozanda aldığın geri ödəniş və ya endirim.","also":["service credit","service credits","xidmət krediti"]}]}};
